  stations = {
    ["01-1"] = {name="Vallée des Épreuves", tips={{k="交通", text="Suis la grande route de Durotar vers le sud, entre dans la Vallée des Épreuves par l'est et retrouve Kaltunk. Le trajet complet est indiqué en haut."}, {k="取捨", text="Fais Armes égarées, Les péons paresseux et les deux quêtes du Convent de la Lame ardente en deux passages."}, {k="取捨", text="Termine d'abord la quête du diablotin Les vils quasits ou Les vils quasits, puis accepte Le médaillon de la Lame ardente auprès de Zureetha Fargaze (démoniste uniquement).", s={{"Termine d'abord la quête du diablotin Les vils quasits ou Les vils quasits, puis accepte Le médaillon de la Lame ardente auprès de Zureetha Fargaze (démoniste uniquement).", {class={"WARLOCK"}}}}}, {k="提醒", text="En dessous du niveau 6? Tue des sangliers tachetés, des scorpides ouvriers ou des vils quasits sur le chemin de Sen'jin.", s={{"En dessous du niveau 6?"}, {"Tue des sangliers tachetés, des scorpides ouvriers ou des vils quasits sur le chemin de Sen'jin"}}}}, danger={[1]="Au tournant du Convent de la Lame ardente, tu risques d'attirer plusieurs vils quasits. Nettoie l'entrée avant de prendre la pioche pour garder une sortie."}, grind={[1]={mob="Sanglier tacheté", note="Des foules normales denses, pour la plupart neutres. Tire-les une par une au nord de la Vallée des Épreuves pour La dent tranchante aux niveaux 1 et 2."}, [2]={mob="Scorpide ouvrier", note="Beaucoup de créatures ordinaires, surtout neutres, au nord-ouest de L'Antre. Attire-les une par une pendant L'aiguillon du scorpide."}, [3]={mob="Vil quasit", note="Beaucoup de créatures normales près du Convent de la Lame ardente. Attire-les une par une depuis l'extérieur. Atteins le niveau 6 avant de quitter la vallée."}}, supply={[1]={npc="Rarc"}, [2]={npc="Zlagk"}, [3]={npc="Duokna"}}, steps={[1]={npc="Kaltunk", tgt="Kaltunk"}, [2]={hint="Parler à Gornek. Souvenez-vous que Kaltunk vous a indiqué où il se trouvait sur votre carte et vous a dit que Gornek résidait dans l'Antre, un bâtiment vers l'ouest."}, [3]={npc="Gornek", tgt="Gornek"}, [4]={npc="Bon-cadeau (Vallée des épreuves)", npcObj=true, tag="Facultatif, À vérifier en jeu", desc="N'accepte la quête que si tu as le bon-cadeau de la Vallée des Épreuves. Le bon est déjà dans le sac des personnages de la race d'origine; fais un clic droit dessus, car il n'y a pas de point de départ sur la carte."}, [5]={hint="Apporter le Bon-cadeau (Vallée des Epreuves) à Magga.", tag="Facultatif", desc="N'accepte la quête que si tu as le bon-cadeau de la Vallée des Épreuves."}, [6]={npc="Magga", tgt="Magga", tag="Facultatif", desc="N'accepte la quête que si tu as le bon-cadeau de la Vallée des Épreuves."}, [7]={npc="Gornek", tgt="Gornek"}, [8]={npc="Gornek", tgt="Gornek"}, [9]={hint="Tuer 10 Sangliers tachetés, puis retourner voir Gornek, dans l'Antre."}, [10]={hint="Récupérez 6 armes d'entraînement abandonnées, puis retournez auprès de Kzan Trancheronce, dans l'Antre."}, [11]={npc="Gornek", tgt="Gornek"}, [12]={npc="Kzan Thornslash", tgt="Kzan Thornslash"}, [13]={npc="Gornek", tgt="Gornek"}, [14]={npc="Galgar", tgt="Galgar"}, [15]={npc="Contremaître Thazz'ril", tgt="Contremaître Thazz'ril"}, [16]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [17]={text="Nettoie d'abord la vallée de départ, puis va à la grotte au nord"}, [18]={hint="Apporter 10 Queues de scorpides ouvriers à Gornek, dans l'Antre."}, [19]={hint="Apportez à Galgar 10 Pommes de cactus. Il vous a précisé qu'elles se trouvaient souvent à côté des cactus."}, [20]={hint="Utiliser la Masse du contremaître sur les Péons paresseux, lorsqu'ils sont en train de dormir. Réveiller 5 Péons, puis rapporter la Masse du contremaître au contremaître Thazz'ril, dans la Vallée des épreuves.", desc="Réveille cinq péons endormis avec le gourdin du contremaître."}, [21]={hint="Tuer 12 Vils quasits.", desc="Si tu joues démoniste, suis la quête du diablotin de Ruzan. Voir les quêtes de classe."}, [22]={npc="Hana'zua", tgt="Hana'zua", tag="Facultatif"}, [23