    ["01-2"] = {name="Durotar", nameA="Durotar: {a:367} & {a:362}", shortA="Durotar: {a:367} +", tips={{k="取捨", text="Fais Assumer ses responsabilités. Récupère les Morceaux de canevas en même temps que les autres objectifs du donjon de Tiragarde."}, {k="取捨", text="Rends Vaincre les traîtres pour débloquer Des épaves. Fais-les en même temps que Un esprit parfaitement éduqué."}, {k="取捨", text="Garde la chaîne de donjon de la Faille de l'Ombre pour plus tard. Prends Ennemis cachés (→→) auprès de Thrall si tu comptes faire le Gouffre de Ragefeu. Récupère l'insigne pour au camp de la Lame ardente au nord."}, {k="提醒", text="En dessous du niveau 12? Fais Des lignes sécurisées, Rocher du crâne ou les premières étapes d'Une menace venue d'en bas.", s={{"En dessous du niveau 12?"}, {"Fais Des lignes sécurisées, Rocher du crâne ou les premières étapes d'Une menace venue d'en bas"}}}}, danger={[1]="Les escaliers et les portes du Donjon de Tiragarde peuvent attirer les marins de l'étage. Dégage d'abord le mur extérieur et l'entrée.", [2]="Les géants des mers de la côte nord rôdent près de la zone des nagas. Élimine d'abord les monstres autour avant d'en attirer un. Si ça tourne mal, replie-toi le long du rivage."}, grind={[1]={mob="Soldat de marine de Kul Tiras", note="Des foules normales denses au donjon de Tiragarde. Attire-les à l'extérieur pour éviter d'en tirer d'autres dans les couloirs. Récupère les Morceaux de canevas pour Assumer ses responsabilités."}, [2]={mob="Garde de guerre Tranchecrin", note="Les foules normales se regroupent à l'ouest de Tranchecolline. Longe le bord du camp et surveille les patrouilles. Fais-le en même temps qu'Empiètement."}, [3]={mob="Sorcière des tempêtes Terrevent", note="Les foules normales se regroupent dans le nord de Durotar, avec des lanceurs de sorts. Tire-les depuis un abri. Fais Des lignes sécurisées ou farme jusqu'au niveau 12 avant Orgrimmar."}}, supply={[1]={npc="Trayexir"}, [2]={npc="Grosk l'aubergiste"}, [3]={npc="Wuark"}, [4]={npc="Grosk l'aubergiste"}, [5]={npc="Ghrawt"}, [6]={npc="Doras"}}, steps={[1]={npc="Ukor", tgt="Ukor", desc="Trouve Ukor sur la route entre la Vallée des Épreuves et Sen'jin."}, [2]={hint="Parler à Maître Gadrin au village de Sen'jin."}, [3]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [4]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [5]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [6]={npc="Maître Vornal", tgt="Maître Vornal"}, [7]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [8]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [9]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [10]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [11]={npc="Xar'Ti", tgt="Xar'Ti"}, [12]={npc="Maître Vornal", tgt="Maître Vornal"}, [13]={npc="Pa'zula", tgt="Pa'zula", tag="Facultatif", desc="Fais la quête seulement si tu peux obtenir les composants de désenchantement."}, [14]={text="Passe d'abord à Tranchecolline"}, [15]={hint="Tuez 6 rampantes noirecrêtes et 6 rôdeuses noirecrêtes dans le sud de Durotar, puis informez-en Gar'thok à Tranchecolline."}, [16]={hint="Apportez le journal à Brakk près de Tranchecolline.", tag="Facultatif"}, [17]={npc="Brakk", tgt="Brakk", tag="Facultatif"}, [18]={npc="Brakk", tgt="Brakk", tag="Facultatif"}, [19]={hint="Asseyez-vous près du feu de camp basique de Brakk et attendez de recevoir l'amélioration Repos amplifié.", tag="Facultatif"}, [20]={npc="Brakk", tgt="Brakk", tag="Facultatif"}, [21]={npc="Brakk", tgt="Brakk", tag="Facultatif"}, [22]={npc="Brakk", tgt="Brakk", tag="Facultatif", desc="Fais la quête après avoir appris le Dépeçage. Rends-la à Orgrimmar."}, [23]={hint="Parler à Orgnil Soulscar à Tranchecolline."}, [24]={hint="Apporter le Fardeau d'Ukor à l'aubergiste Grosk à Tranchecolline."}, [25]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [26]={npc="Gar'Thok", tgt="Gar'Thok"}, [27]={npc="Grosk l'aubergiste", tgt="Grosk l'aubergiste"}, [28]={text="Lie d'abord ta pierre de foyer auprès de Grosk l'aubergiste à Tranchecolline (51.51, 41.64)."}, [29]={npc="Gar'Thok", tgt="Gar'Thok"}, [30]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [31]={npc="Cuisinier Torka", tgt="Cuisinier Torka"}, [32]={npc="Gar'Thok", tgt="Gar'Thok"}, [33]={npc="Furl Scornbrow", tgt="Furl Scornbrow", star={"Sac en cuir fait main"}}, [34]={npc="Turroc", tgt="Turroc"}, [35]={npc="Cuisinier Torka", tgt="Cuisinier Torka"}, [36]={hint="Parlez au cuisinier Torka, à Tranchecolline, pour apprendre à cuisiner.", tag="Facultatif"}, [37]={npc="Cuisinier Torka", tgt="Cuisinier Torka", tag="Facultatif"}, [38]={text="Donjon de Tiragarde → les épaves → Combe des Kolkar et Îles de l'Écho"}, [39]={hint="Tuer 10 Marins de Kul Tiras, 8 Soldats de marine de Kul Tiras et le Lieutenant Benedict, puis retourner voir Gar'Thok à Tranchecolline."}, [40]={hint="Apporter 8 Morceaux de canevas à Furl Scornbrow, dans la la tour de guet de Tranchecolline."}, [41]={hint="Récupérez la hache d'armes d'écumeur, l'arc d'écumeur et le bouclier d'écumeur aux alentours du donjon de Tiragarde, puis rapportez-les à Turroc à Tranchecolline."}, [42]={npc="Vieille enveloppe", npcObj=true, desc="Tue le lieutenant Benedict pour prendre la clé, puis ouvre le coffre à l'étage pour obtenir la Vieille enveloppe."}, [43]={npc="Sac perdu d'Ukor", npcObj=true, tag="Facultatif", desc="Prends la quête seulement si tu trouves le sac en passant. Va au sud voir Ukor."}, [44]={text="Retourne à Tranchecolline depuis le donjon de Tiragarde, avec ta pierre de foyer si elle est prête."}, [45]={hint="Apporter les Ordres de l'amiral Proudmoore à Gar'Thok de Tranchecolline."}, [46]={npc="Gar'Thok", tgt="Gar'Thok"}, [47]={npc="Gar'Thok", tgt="Gar'Thok"}, [48]={npc="Turroc", tgt="Turroc", desc="Tu peux aussi prendre la quête auprès du Grunt de Tranchecolline (53.06, 42.48)."}, [49]={npc="Furl Scornbrow", tgt="Furl Scornbrow", star={"Sac en cuir fait main"}}, [50]={npc="Gar'Thok", tgt="Gar'Thok"}, [51]={npc="Gar'Thok", tgt="Gar'Thok", tag="Facultatif"}, [52]={hint="Apporter 4 Yeux de makrura intacts et 8 Fioles de mucus de clampant à maître Vornal, au village de Sen'jin."}, [53]={hint="Gar'Thok de Tranchecolline veut que vous retrouviez 3 Outils gnomes parmi les épaves près de la côte."}, [54]={hint="Rapportez son sac à Ukor dans le sud de Durotar.", tag="Facultatif"}, [55]={npc="Ukor", tgt="Ukor", tag="Facultatif"}, [56]={npc="Maître Vornal", tgt="Maître Vornal"}, [57]={hint="Détruire 3 Jeux de Plans d'attaque dans la combe des Kolkar, pour Lar Prowltusk à l'extérieur du village de Sen'jin."}, [58]={npc="Pal'juh", tgt="Pal'juh", tag="Facultatif", desc="Trouve Pal'juh dans la Combe des Kolkar. Dégage d'abord la route avant de démarrer l'escorte pour ne pas attirer d'autres monstres."}, [59]={hint="Aidez Pal'juh à sortir de la combe des Kolkar, puis informez-en maître Vornal, au village de Sen'jin.", tag="Facultatif", desc="Trouve Pal'juh dans la Combe des Kolkar. Dégage d'abord la route avant de démarrer l'escorte pour ne pas attirer d'autres monstres."}, [60]={npc="Maître Vornal", tgt="Maître Vornal", tag="Facultatif", desc="Trouve Pal'juh dans la Combe des Kolkar. Dégage d'abord la route avant de démarrer l'escorte pour ne pas attirer d'autres monstres."}, [61]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [62]={hint="Rapporter 3 Oeufs de fouette-queue au cuisinier Torka, à Tranchecolline."}, [63]={hint="Apporter 4 Peaux de tigres de Durotar à Vel'rin Fang, au village de Sen'jin."}, [64]={hint="Récupérer le Crâne de Minshina dans le Cercle de puissance, sur les îles de l'Écho."}, [65]={hint="Battre Zalazane."}, [66]={hint="Récupérez 8 idoles de Loas oubliées sur les îles de l'Écho. Apportez-les au maître Gadrin, au village de Sen'jin."}, [67]={hint="Apportez les œufs de la matriarche griffesang à Xar'Ti, au village de Sen'jin."}, [68]={hint="Pa'zula du village de Sen'jin vous demande de récupérer 3 résidus lumineux. Vous pourrez obtenir des résidus lumineux en désenchantant les pendentifs maléficiés obtenus sur les Trolls des îles de l'Écho.", tag="Facultatif", desc="Cette zone fait partie des endroits où tombe le pendentif Maléfice. Le Résidu lumineux vient du désenchantement."}, [69]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [70]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [71]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [72]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [73]={npc="Xar'Ti", tgt="Xar'Ti"}, [74]={npc="Pa'zula", tgt="Pa'zula", tag="Facultatif"}, [75]={text="Utilise ta pierre de foyer pour revenir à Tranchecolline, ou prends la route du nord."}, [76]={npc="Cuisinier Torka", tgt="Cuisinier Torka"}, [77]={npc="Gar'Thok", tgt="Gar'Thok"}, [78]={text="À l'ouest de Tranchecolline et au nord de Durotar"}, [79]={hint="Tuer 4 hurans Tranchecrin, 4 Eclaireurs Tranchecrin, 4 Lève-poussière Tranchecrin et 4 Gardes de guerre Tranchecrin pour Gar'Thok de Tranchecolline."}, [80]={hint="Le cuisinier Torka de Tranchecolline souhaite que vous ramassiez 8 figues de Barbarie dans les terres des Tranchecrins à l'ouest de la ville."}, [81]={npc="Gar'Thok", tgt="Gar'Thok"}, [82]={npc="Cuisinier Torka", tgt="Cuisinier Torka"}, [83]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", desc="Niveau 9 minimum."}, [84]={hint="Trouvez Heglan Ombredœil au nord du donjon de Tiragarde.", desc="Niveau 9 minimum."}, [85]={npc="Heglan Ombredoeil", tgt="Heglan Ombredoeil", desc="Niveau 9 minimum."}, [86]={npc="Heglan Ombredoeil", tgt="Heglan Ombredoeil"}, [87]={hint="Trouvez des traces de ce qui a attaqué Heglan Ombredœil."}, [88]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [89]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [90]={hint="Apporter la Griffe de Fizzle à Orgnil Soulscar à Tranchecolline."}, [91]={hint="Récupérez 9 ailerons épineux de Nagas."}, [92]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [93]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [94]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", tag="Facultatif", desc="Géant des mers d'élite sur la côte nord. Fais équipe ou passe-le si tu n'y arrives pas."}, [95]={hint="Tuez le Géant des mers au large de la côte nord de Durotar, puis rapportez une preuve de votre victoire.", tag="Facultatif", desc="Géant des mers d'élite sur la côte nord. Fais équipe ou passe-le si tu n'y arrives pas."}, [96]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", tag="Facultatif", desc="Géant des mers d'élite sur la côte nord. Fais équipe ou passe-le si tu n'y arrives pas."}, [97]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [98]={hint="Parler à Margoz."}, [99]={npc="Margoz", tgt="Margoz"}, [100]={npc="Margoz", tgt="Margoz"}, [101]={hint="Prendre les Colliers brûlants des sectateurs au Rocher du crâne."}, [102]={npc="Margoz", tgt="Margoz"}, [103]={npc="Margoz", tgt="Margoz", tag="Facultatif"}, [104]={text="XP en option avant le niveau 12"}, [105]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [106]={hint="Retrouver 5 Sacs de marchandises et les rendre à Rezlak près d'Orgrimmar.", tag="Facultatif"}, [107]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [108]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [109]={hint="Tuer 12 Terrevent farouches et 8 Sorcières des tempêtes Terrevent pour Rezlak près du Ravin asséché.", tag="Facultatif"}, [110]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [111]={npc="Misha Tor'kren", tgt="Misha Tor'kren", tag="Facultatif"}, [112]={hint="Trouver un indice du sort de Kron et en informer Misha Tor'kren, à la ferme, au nord-ouest de Tranchecolline.", tag="Facultatif"}, [113]={npc="Misha Tor'kren", tgt="Misha Tor'kren", tag="Facultatif"}, [114]={npc="Orbe de tempête émoussé", npcObj=true, tag="Facultatif", desc="Accepte la quête uniquement si tu ramasses l'Orbe de tempête émoussé."}, [115]={hint="Apportez l'orbe de tempête émoussé à Rezlak, près du ravin Asséché.", tag="Facultatif", desc="Accepte la quête uniquement si tu ramasses l'Orbe de tempête émoussé."}, [116]={npc="Rezlak", tgt="Rezlak", tag="Facultatif", desc="Accepte la quête uniquement si tu ramasses l'Orbe de tempête émoussé."}, [117]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [118]={hint="Apportez 5 organes de lézard-tonnerre chargés à Rezlak, près du ravin Asséché.", tag="Facultatif"}, [119]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [120]={npc="Sabot d'Halikor", npcObj=true, tag="Facultatif", desc="Si tu croises Halikor et que tu peux le tuer, prends son sabot."}, [121]={text="Orgrimmar sur le trajet, puis remises à La Croisée"}, [122]={text="Si tu as des quêtes à rendre ou un entraînement à faire à Orgrimmar, suis la grande route de Durotar vers le nord et entre par la porte sud. Apprends le point de vol de Doras (45.12, 63.89) et rends au passage la prochaine série de quêtes de la ville."}, [123]={hint="Porter les Ordres de l'amiral Proudmoore à Nazgrel, dans les appartements de Thrall à Orgrimmar.", tag="Facultatif"}, [124]={npc="Nazgrel", tgt="Nazgrel", tag="Facultatif"}, [125]={hint="Apporter un Spécimen de collier à Neeru Fireblade à Orgrimmar.", tag="Facultatif"}, [126]={npc="Neeru Fireblade", tgt="Neeru Fireblade", tag="Facultatif"}, [127]={hint="Parlez à Thuwd, à Orgrimmar, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tag="Facultatif"}, [128]={npc="Thuwd", tgt="Thuwd", tag="Facultatif"}, [129]={hint="Rapportez le sabot d'Halikor à Orgrimmar.", tag="Facultatif"}, [130]={npc="Kamari", tgt="Kamari", tag="Facultatif"}, [131]={text="Rends d'abord les quêtes en ville, puis utilise ta pierre de foyer pour rejoindre Tranchecolline. Si elle est en recharge, suis la grande route de Durotar vers le sud. Si tu n'es pas entré en ville, passe à l'étape suivante."}, [132]={npc="Pisteur Takrin", tgt="Pisteur Takrin", desc="Niveau 10 minimum. Attends d'être niveau 12 environ avant d'aller à La Croisée."}, [133]={hint="Suivre la route de l'ouest, celle qui part de Tranchecolline, et qui arrive aux Tarides par un pont."}, [134]={npc="Kargal Battlescar", tgt="Kargal Battlescar"}, [135]={npc="Kargal Battlescar", tgt="Kargal Battlescar"}, [136]={text="Va vers l'ouest depuis le Poste de garde extérieur. Tourne vers le sud au carrefour en T pour arriver à La Croisée, dans les Tarides."}, [137]={hint="Suivre la route à l'ouest à partir du Poste de garde extérieur de Kargal."}, [138]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [139]={npc="Kaplak", tgt="Kaplak", desc="Quête d'introduction des orcs. Les trolls peuvent prendre La Main brisée directement auprès de Therzok."}, [140]={hint="Aller voir Therzok dans la Faille de l'ombre à Orgrimmar.", desc="Quête d'introduction des orcs. Les trolls peuvent prendre La Main brisée directement auprès de Therzok."}, [141]={npc="Therzok", tgt="Therzok", desc="Quête d'introduction des orcs. Les trolls peuvent prendre La Main brisée directement auprès de Therzok."}, [142]={npc="Therzok", tgt="Therzok", desc="Vole d'abord la clé de Tazan, puis récupère son sac. Garde la clé pour la suite."}, [143]={hint="Tuer Tazan et apporter sa Sacoche à Therzok, à la Faille de l'ombre à Orgrimmar.", desc="Vole d'abord la clé de Tazan, puis récupère son sac. Garde la clé pour la suite."}, [144]={npc="Therzok", tgt="Therzok", desc="Vole d'abord la clé de Tazan, puis récupère son sac. Garde la clé pour la suite."}, [145]={npc="Therzok", tgt="Therzok", desc="Conserve la clé et attends que Therzok te propose La Main brisée avant d'ouvrir le sac.", star={"Lame de malice", {"ROGUE"}}}, [146]={hint="Voler la Clé de Tazan puis l'utiliser pour ouvrir sa Sacoche et livrer son contenu à Therzok dans la Faille de l'ombre à Orgrimmar.", desc="Conserve la clé et attends que Therzok te propose La Main brisée avant d'ouvrir le sac."}, [147]={npc="Therzok", tgt="Therzok", desc="Conserve la clé et attends que Therzok te propose La Main brisée avant d'ouvrir le sac.", star={"Lame de malice", {"ROGUE"}}}, [148]={npc="Swart", tgt="Swart", desc="Commence à Tranchecolline. La suite de Kranal est commune avec l'introduction de Sabot-de-Sang (voir La Croisée) : il suffit de faire une seule des deux séries."}, [149]={hint="Trouver Kranal Fiss dans les Tarides.", desc="Commence à Tranchecolline. La suite de Kranal est commune avec l'introduction de Sabot-de-Sang (voir La Croisée) : il suffit de faire une seule des deux séries."}, [150]={npc="Kranal Fiss", tgt="Kranal Fiss", desc="Commence à Tranchecolline. La suite de Kranal est commune avec l'introduction de Sabot-de-Sang (voir La Croisée) : il suffit de faire une seule des deux séries."}, [151]={npc="Sian'dur", tgt="Sian'dur", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès de Thotar."}, [152]={hint="Parler à Thotar, à Tranchecolline.", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès de Thotar."}, [153]={npc="Thotar", tgt="Thotar", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès de Thotar."}, [154]={npc="Kali Remik", tgt="Kali Remik", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès de Thotar."}, [155]={hint="Parler à Thotar, à Tranchecolline.", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès de Thotar."}, [156]={npc="Thotar", tgt="Thotar", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès de Thotar."}, [157]={npc="Kary Thunderhorn", tgt="Kary Thunderhorn", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès de Thotar."}, [158]={hint="Parler à Thotar, à Tranchecolline.", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès de Thotar."}, [159]={npc="Thotar", tgt="Thotar", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès de Thotar."}, [160]={npc="Thotar", tgt="Thotar"}, [161]={hint="Utiliser le Bâtonnet de domptage pour dompter un sanglier tacheté redoutable. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar de Tranchecolline."}, [162]={npc="Thotar", tgt="Thotar"}, [163]={npc="Thotar", tgt="Thotar", desc="Prérequis : Dompter la bête. La deuxième cible est un Clampant de l'écume."}, [164]={hint="Utiliser le Bâtonnet de domptage pour dompter un Clampant de l'écume. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar, à Tranchecolline.", desc="Prérequis : Dompter la bête. La deuxième cible est un Clampant de l'écume."}, [165]={npc="Thotar", tgt="Thotar", desc="Prérequis : Dompter la bête. La deuxième cible est un Clampant de l'écume."}, [166]={npc="Thotar", tgt="Thotar", desc="Prérequis : Dompter la bête. Apprivoise un Scorpide blindé en troisième."}, [167]={hint="Domptez un Scorpide blindé à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Thotar à Tranchecolline.", desc="Prérequis : Dompter la bête. Apprivoise un Scorpide blindé en troisième."}, [168]={npc="Thotar", tgt="Thotar", desc="Prérequis : Dompter la bête. Apprivoise un Scorpide blindé en troisième."}, [169]={npc="Thotar", tgt="Thotar", desc="Après avoir dompté la bête, va à la Vallée de l'Honneur d'Orgrimmar pour apprendre les compétences d'entraînement des familiers."}, [170]={hint="Adressez-vous à Orkmar Grimshot à Orgrimmar.", desc="Après avoir dompté la bête, va à la Vallée de l'Honneur d'Orgrimmar pour apprendre les compétences d'entraînement des familiers."}, [171]={npc="Ormak Grimshot", tgt="Ormak Grimshot", desc="Après avoir dompté la bête, va à la Vallée de l'Honneur d'Orgrimmar pour apprendre les compétences d'entraînement des familiers."}, [172]={npc="Ophek", tgt="Ophek", tag="Facultatif", desc="Tu peux ignorer l'introduction. La quête est ouverte aux démonistes de la Horde."}, [173]={hint="Parler à Gan'rul Bloodeye à Orgrimmar.", tag="Facultatif", desc="Tu peux ignorer l'introduction. La quête est ouverte aux démonistes de la Horde."}, [174]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", tag="Facultatif", desc="Tu peux ignorer l'introduction. La quête est ouverte aux démonistes de la Horde."}, [175]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Récupère la tablette dans la grotte du Rocher du crâne, à l'est d'Orgrimmar."}, [176]={hint="Récupérer la Tablette de Verga pour Gan'rul Bloodeye à Orgrimmar.", desc="Récupère la tablette dans la grotte du Rocher du crâne, à l'est d'Orgrimmar."}, [177]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Récupère la tablette dans la grotte du Rocher du crâne, à l'est d'Orgrimmar."}, [178]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Utilise l'inscription sur le cercle d'invocation près de Neeru, bats le Marcheur du Vide, puis rends la quête à Gan'rul."}, [179]={hint="Utiliser les Glyphes d'invocation pour invoquer et soumettre un marcheur du Vide, puis rapporter les Glyphes d'invocation à Gan'rul Bloodeye, à Orgrimmar.", desc="Utilise l'inscription sur le cercle d'invocation près de Neeru, bats le Marcheur du Vide, puis rends la quête à Gan'rul."}, [180]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Utilise l'inscription sur le cercle d'invocation près de Neeru, bats le Marcheur du Vide, puis rends la quête à Gan'rul."}, [181]={npc="Tai'jin", tgt="Tai'jin", desc="Entraîne d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [182]={hint="Trouver le grunt Kor'ja et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Tai'jin, sur Tranchecolline.", desc="Entraîne d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [183]={npc="Tai'jin", tgt="Tai'jin", desc="Entraîne d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [184]={npc="Tai'jin", tgt="Tai'jin"}, [185]={hint="Parler à Ur'kyo à Orgrimmar."}, [186]={npc="Ur'kyo", tgt="Ur'kyo"}, [187]={npc="Ur'kyo", tgt="Ur'kyo"}, [188]={hint="Remplissez les objectifs de la quête."}, [189]={npc="Ur'kyo", tgt="Ur'kyo"}, [190]={npc="Uthel'nay", tgt="Uthel'nay", tag="Facultatif", desc="Prends la quête à Orgrimmar auprès d'Uthel'nay ou aux Pitons-du-Tonnerre auprès de Thurston Xane (25.18, 20.96). À Sen'jin, prends directement Les Tas de Ju-Ju auprès d'Un'Thuwa."}, [191]={hint="Aller voir Un'thuwa.", tag="Facultatif", desc="Si tu es au village de Sen'jin, prends directement Les Tas de Ju-Ju auprès d'Un'Thuwa."}, [192]={npc="Un'Thuwa", tgt="Un'Thuwa", tag="Facultatif", desc="Si tu es au village de Sen'jin, prends directement Les Tas de Ju-Ju auprès d'Un'Thuwa."}, [193]={npc="Un'Thuwa", tgt="Un'Thuwa"}, [194]={hint="Détruire 4 Tas de Ju-Ju, puis retourner voir Un'thuwa au village de Sen'jin."}, [195]={npc="Un'Thuwa", tgt="Un'Thuwa"}, [196]={text="Apprends le point de vol de Devrak à La Croisée (51.50, 30.34). Tu peux lier ta pierre de foyer auprès de Boorand Plainswind l'aubergiste (51.99, 29.89)."}}},
    ["01-3"] = {name="Camp Narache", tips={{k="交通", text="Si tu viens d'une autre zone de départ, va d'abord à Sabot-de-Sang, puis suis la route vers le sud jusqu'à la Mesa de Nuage rouge et au Camp Narache. Trajet complet en haut de page."}, {k="取捨", text="Fais Le Rite de force, La fin de Brochaigu! et Les sangliers de guerre apprivoisés d'une traite dans le Ravin de Roncelame. Accepte L'attaque du Camp Narache si tu ramasses la carte."}, {k="提醒", text="En dessous du niveau 6? Tue des sangliers de guerre ou des Huran Dos-hirsute au bord du Ravin de Roncelame, puis va à Sabot-de-Sang.", s={{"En dessous du niveau 6?"}, {"Tue des sangliers de guerre ou des Huran Dos-hirsute au bord du Ravin de Roncelame, puis va à Sabot-de-Sang"}}}}, danger={[1]="Les quilboars du Ravin de Roncelame se concentrent sur une rampe étroite. Dégage-la avant d'attirer Chef Brochaigu Mantépine. Replie-toi vers la Mesa de Nuage rouge."}, grind={[1]={mob="Trotteur des plaines", note="Des foules normales denses et pour la plupart neutres près du puits sud-est de Camp Narache. Tire un ennemi à la fois pendant La chasse commence."}, [2]={mob="Puma des montagnes", note="Des foules normales denses et pour la plupart neutres sur le versant sud de Mesa de Nuage rouge. Tire un ennemi à la fois pour obtenir les peaux nécessaires dans La chasse continue."}, [3]={mob="Sanglier de guerre Dos-hirsute", note="Les foules normales se regroupent parmi Huran Dos-hirsute dans Ravin de Roncelame. Dégage d'abord les bords. Associe-le avec Sanglier de guerre et Le Rite de force."}}, supply={[1]={npc="Bronk Steelrage"}, [2]={npc="Moodan Sungrain"}, [3]={npc="Kawnie Softbreeze"}}, steps={[1]={npc="Bon-cadeau (Camp Narache)", npcObj=true, tag="Facultatif, À vérifier en jeu", desc="Accepte la quête uniquement si tu possèdes le bon-cadeau du Camp Narache. Le bon est déjà dans le sac des personnages de la race d'origine; fais un clic droit dessus, car il n'y a pas de point de départ sur la carte."}, [2]={hint="Apporter le Bon-cadeau (Camp Narache) à Vorn Skyseer.", tag="Facultatif", desc="Accepte la quête uniquement si tu possèdes le bon-cadeau du Camp Narache."}, [3]={npc="Vorn Skyseer", tgt="Vorn Skyseer", tag="Facultatif", desc="Accepte la quête uniquement si tu possèdes le bon-cadeau du Camp Narache."}, [4]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [5]={npc="Chef Hawkwind", tgt="Chef Hawkwind"}, [6]={hint="Grull Hawkwind, à Camp Narache voudrait que vous lui apportiez 7 Plumes de trotteurs des plaines et 7 morceaux de Viande de trotteur des plaines."}, [7]={hint="Partir chercher la mère du Chef Hawkwind, près du puits, au sud-est de Camp Narache."}, [8]={npc="Grand-mère Hawkwind", tgt="Grand-mère Hawkwind"}, [9]={npc="Grand-mère Hawkwind", tgt="Grand-mère Hawkwind"}, [10]={hint="Prendre une Cruche d'eau du puits.", desc="Récupère la Cruche d'eau dans le puits à côté de Grand-mère Hawkwind."}, [11]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [12]={npc="Chef Hawkwind", tgt="Chef Hawkwind"}, [13]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [14]={npc="Chef Hawkwind", tgt="Chef Hawkwind"}, [15]={npc="Brave Windfeather", tgt="Brave Windfeather"}, [16]={hint="Grull Hawkwind, à Camp Narache, voudrait que vous lui apportiez 10 Peaux de puma des montagnes."}, [17]={hint="Aller voir le Prophète Graytongue qui vit dans les collines au sud de Camp Narache."}, [18]={npc="Prophète Graytongue", tgt="Prophète Graytongue"}, [19]={npc="Prophète Graytongue", tgt="Prophète Graytongue"}, [20]={npc="Prophète Graytongue", tgt="Prophète Graytongue", tag="Facultatif", desc="Apporte l'encens à l'autel sud-est dans les 10 minutes suivant sa réception.", star={"Bourse en cuir brûlée"}}, [21]={hint="Portez l'encens fumant jusqu'au sanctuaire de An'she et de Mu'sha, dans les collines au sud-est. Vous avez dix minutes avant que l'encens ne soit réduit en cendres !", tag="Facultatif", desc="Apporte l'encens à l'autel sud-est dans les 10 minutes suivant sa réception."}, [22]={npc="Feu rituel", npcObj=true, tag="Facultatif", desc="Apporte l'encens à l'autel sud-est dans les 10 minutes suivant sa réception.", star={"Bourse en cuir brûlée"}}, [23]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [24]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [25]={hint="Tuer des Dos-hirsute dans le Ravin de Roncelame et apporter 12 Ceintures de Dos-hirsute au chef Hawkwind au camp Narache."}, [26]={hint="Apporter la Tête du chef Brochaigu Mantépine à Brave Windfeather à la mesa de Nuage rouge."}, [27]={hint="Grull Hawkwind, à Camp Narache, voudrait que vous tuiez des sangliers de guerre, et que vous rapportiez 8 Groins de sanglier de guerre et 8 Flancs de sanglier de guerre."}, [28]={npc="Carte couverte de poussière", npcObj=true, tag="Facultatif", desc="Récupère la carte tachée de saleté sur Huran Dos-hirsute et fais un clic droit dessus."}, [29]={npc="Chef Hawkwind", tgt="Chef Hawkwind"}, [30]={npc="Brave Windfeather", tgt="Brave Windfeather"}, [31]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [32]={hint="Apporter les Plans d'attaque Dos-hirsute au chef Hawkwind, au camp Narache.", tag="Facultatif"}, [33]={npc="Chef Hawkwind", tgt="Chef Hawkwind", tag="Facultatif"}, [34]={npc="Chef Hawkwind", tgt="Chef Hawkwind"}, [35]={npc="Chef Hawkwind", tgt="Chef Hawkwind", tag="Facultatif"}, [36]={npc="Antur Fallow", tgt="Antur Fallow", tag="Facultatif", desc="Prends la quête auprès d'Antur Fallow en passant à l'ouest du camp."}, [37]={npc="Grull Hawkwind", tgt="Grull Hawkwind", desc="Termine La chasse commence, puis prends la quête d'introduction auprès du maître de classe."}, [38]={hint="Lire la Note simple, et parler à Harutt Thunderhorn, à Camp Narache.", desc="Termine La chasse commence, puis prends la quête d'introduction auprès du maître de classe."}, [39]={npc="Harutt Thunderhorn", tgt="Harutt Thunderhorn", desc="Termine La chasse commence, puis prends la quête d'introduction auprès du maître de classe."}, [40]={npc="Grull Hawkwind", tgt="Grull Hawkwind", desc="Termine La chasse commence, puis prends la quête d'introduction auprès du maître de classe."}, [41]={hint="Lire la Note runique, et parler à Meela Dawnstrider, à Camp Narache.", desc="Termine La chasse commence, puis prends la quête d'introduction auprès du maître de classe."}, [42]={npc="Meela Dawnstrider", tgt="Meela Dawnstrider", desc="Termine La chasse commence, puis prends la quête d'introduction auprès du maître de classe."}, [43]={npc="Prophétesse Ravenfeather", tgt="Prophétesse Ravenfeather"}, [44]={hint="Apporter 2 Applications de Baume rituel au Prophète Ravenfeather au Camp Narache."}, [45]={npc="Prophétesse Ravenfeather", tgt="Prophétesse Ravenfeather"}, [46]={npc="Prophétesse Ravenfeather", tgt="Prophétesse Ravenfeather", desc="Bois le sapta pour voir la manifestation de terre mineure."}, [47]={hint="Trouver le Rocher des kodos et boire le Sapta de terre.", desc="Bois le sapta pour voir la manifestation de terre mineure."}, [48]={npc="Manifestation de terre mineure", tgt="Manifestation de terre mineure", desc="Bois le sapta pour voir la manifestation de terre mineure."}, [49]={npc="Manifestation de terre mineure", tgt="Manifestation de terre mineure", desc="Termine la quête pour obtenir ton Totem de terre."}, [50]={hint="Apporter le Quartz brut à la prophétesse Ravenfeather au Camp Narache.", desc="Termine la quête pour obtenir ton Totem de terre."}, [51]={npc="Prophétesse Ravenfeather", tgt="Prophétesse Ravenfeather", desc="Termine la quête pour obtenir ton Totem de terre."}, [52]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [53]={hint="Lire la Note gravée, et parler à Lanka Farshot, sur la Mesa de Nuage rouge."}, [54]={npc="Lanka Farshot", tgt="Lanka Farshot"}, [55]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [56]={hint="Lire la Note verdoyante, et parler à Gart Mistrunner, à Camp Narache."}, [57]={npc="Gart Mistrunner", tgt="Gart Mistrunner"}, [58]={text="Quitte la Mesa de Nuage rouge et suis la route vers le nord jusqu'à Sabot-de-Sang."}}},
    ["01-4"] = {name="Mulgore", nameA="Mulgore: {a:222}", tips={{k="取捨", text="Fais Le Rite de vision (→→), Le Rite de sagesse et Voyage à Thunder Bluff. Le dernier tronçon débloque justement un point de vol."}, {k="取捨", text="Termine chaque quête de puits avant de prendre la suivante (Taurens uniquement). Au niveau 12, tu peux ignorer la chaîne des puits de Wildmane (Taurens uniquement).", s={{"Termine chaque quête de puits avant de prendre la suivante (Taurens uniquement). Au niveau 12, tu peux ignorer la chaîne des puits de Wildmane (Taurens uniquement).", {race={"Tauren"}}}}}, {k="取捨", text="En arrivant aux Pitons-du-Tonnerre, tu peux prendre les prérequis du Gouffre de Ragefeu. Prends Tester la force de l'ennemi et À la recherche de la sacoche perdue auprès de Rahauro seulement si tu comptes y entrer."}, {k="提醒", text="Il te manque de l'XP pour le niveau 12? Farme les harpies du nord de Mulgore, les Rochers rouges ou la mine de la KapitalRisk. Les quêtes de classe de niveau 10 sont en bas de page.", s={{"Il te manque de l'XP pour le niveau 12?"}, {"Farme les harpies du nord de Mulgore, les Rochers rouges ou la mine de la KapitalRisk"}, {"Les quêtes de classe de niveau 10 sont en bas de page"}}}}, danger={[1]="À la mine de la KapitalRisk, patrouilles et mineurs peuvent se joindre au combat. Nettoie d'abord l'extérieur, prends la planchette à notes et ressors du tunnel."}, grind={[1]={mob="Traqueur des prairies", note="Des foules normales dispersées au nord de Sabot-de-Sang. Tire un ennemi à la fois dans l'herbe et surveillez les vagabonds. Récupère les matériaux Mazzranache."}, [2]={mob="Superviseur de la KapitalRisk", note="Les foules normales se regroupent autour de la mine de la KapitalRisk, mêlées à des ouvriers et des patrouilles. Tire-les depuis l'extérieur de la mine. Fais-le en même temps que les quêtes de la mine."}, [3]={mob="Matriarche Furie-des-vents", note="Des foules normales denses au camp de harpies au nord-ouest de Mulgore, avec des harpies lanceuses de sorts. Tire-les depuis le bord du camp. Farme ici si tu es proche du niveau 12."}}, supply={[1]={npc="Kauth l'aubergiste"}, [2]={npc="Harant Ironbrace"}, [3]={npc="Kauth l'aubergiste"}, [4]={npc="Kennah Hawkseye"}, [5]={npc="Tal"}}, steps={[1]={hint="Apportez le paquet de fournitures à Kaga Sabot-sauvage près de Sabot-de-Sang.", tag="Facultatif"}, [2]={npc="Kaga Sabot-sauvage", tgt="Kaga Sabot-sauvage", tag="Facultatif"}, [3]={npc="Kaga Sabot-sauvage", tgt="Kaga Sabot-sauvage", tag="Facultatif"}, [4]={hint="Asseyez-vous près du feu de camp basique de Kaga et attendez de recevoir l'amélioration Repos amplifié.", tag="Facultatif"}, [5]={npc="Kaga Sabot-sauvage", tgt="Kaga Sabot-sauvage", tag="Facultatif"}, [6]={npc="Kaga Sabot-sauvage", tgt="Kaga Sabot-sauvage", tag="Facultatif"}, [7]={npc="Kaga Sabot-sauvage", tgt="Kaga Sabot-sauvage", tag="Facultatif", desc="Ne prends la quête qu'après avoir appris le Dépeçage. Rends-la une fois le niveau de métier requis atteint."}, [8]={hint="Apporter le Totem de Hawkwind à Baine Sabot-de-Sang à Sabot-de-Sang. Suivre la route hors du camp Narache."}, [9]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [10]={hint="Livrer le Ballot de fourrures à l'aubergiste Kauth à Sabot-de-Sang.", tag="Facultatif"}, [11]={npc="Kauth l'aubergiste", tgt="Kauth l'aubergiste", tag="Facultatif"}, [12]={text="Lie ta pierre de foyer auprès de Kauth l'aubergiste à Sabot-de-Sang (45.93, 64.16)."}, [13]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [14]={hint="Parler à Zarlman Deux-Lunes, à Sabot-de-Sang."}, [15]={npc="Zarlman Deux-Lunes", tgt="Zarlman Deux-Lunes"}, [16]={npc="Zarlman Deux-Lunes", tgt="Zarlman Deux-Lunes"}, [17]={npc="Harken Windtotem", tgt="Harken Windtotem"}, [18]={npc="Maur Raincaller", tgt="Maur Raincaller"}, [19]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [20]={npc="Brave Wildrunner", tgt="Brave Wildrunner"}, [21]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [22]={npc="Krang Stonehoof", tgt="Krang Stonehoof", tag="Facultatif"}, [23]={hint="Battez 3 autres personnages-joueurs en duel ou guerriers novices pour Tang Sabot-de-Pierre.", tag="Facultatif"}, [24]={npc="Krang Stonehoof", tgt="Krang Stonehoof", tag="Facultatif"}, [25]={npc="Ahab Sabot-de-Blé", tgt="Ahab Sabot-de-Blé", tag="Facultatif"}, [26]={hint="Parlez à Pyall Sabots-Feutrés, à Sabot-de-Sang, pour apprendre à cuisiner.", tag="Facultatif"}, [27]={npc="Pyall Silentstride", tgt="Pyall Silentstride", tag="Facultatif"}, [28]={hint="Parlez à Yonn Entaille-Profonde, à Sabot-de-Sang, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tag="Facultatif"}, [29]={npc="Yonn Deepcut", tgt="Yonn Deepcut", tag="Facultatif"}, [30]={text="À l'est de Sabot-de-Sang → caravane et centaures"}, [31]={hint="Collecter 2 Pierres de puits et 2 Pommes de pin et les rapporter à Zarlman Deux-Lunes, à Sabot-de-Sang."}, [32]={hint="Apporter 8 Trophées de plumes de Rapace à Harken Windtotem, à Sabot-de-Sang."}, [33]={hint="Apporter un Coeur de loup des plaines, un Fémur de puma des basses plaines, une Ecaille de trotteur des plaines et un Gésier de rapace à Maur Raincaller, à Sabot-de-Sang."}, [34]={hint="Apporter 6 Pattes de loup des prairies et 4 Serres de trotteur des plaines à Mull Thunderhorn à Sabot-de-Sang."}, [35]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [36]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [37]={hint="Utiliser le Totem de purification de Winterhoof au puits Winterhoof, puis retourner voir Mull Thunderhorn."}, [38]={hint="Trouvez la longue-marche Malah Longuebrise à l'est de Sabot-de-Sang, près de la frontière de Mulgore."}, [39]={npc="Malah Longuebrise", tgt="Malah Longuebrise"}, [40]={npc="Malah Longuebrise", tgt="Malah Longuebrise"}, [41]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [42]={hint="Examiner le contenu d'une caisse de provisions à la caravane dévastée, pour Morin Cloudstalker."}, [43]={npc="Caisse de ravitaillements scellée", npcObj=true}, [44]={npc="Caisse de ravitaillements scellée", npcObj=true}, [45]={hint="Rapporter les Documents de la KapitalRisk à Morin Cloudstalker, à côté de Sabot-de-Sang."}, [46]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [47]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [48]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [49]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [50]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [51]={hint="Apportez le rapport de la longue-marche Malah au brave Course-Sauvage à Sabot-de-Sang."}, [52]={npc="Brave Wildrunner", tgt="Brave Wildrunner"}, [53]={npc="Brave Wildrunner", tgt="Brave Wildrunner"}, [54]={hint="Apportez le rapport de la longue-marche Malah à Baine Sabot-de-Sang."}, [55]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [56]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [57]={npc="Zarlman Deux-Lunes", tgt="Zarlman Deux-Lunes"}, [58]={npc="Harken Windtotem", tgt="Harken Windtotem"}, [59]={npc="Zarlman Deux-Lunes", tgt="Zarlman Deux-Lunes"}, [60]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [61]={npc="Ruul Eagletalon", tgt="Ruul Eagletalon"}, [62]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Facultatif"}, [63]={text="Ouest : Palemane et le chantier de fouilles. Suis la vision jusqu'au voyant"}, [64]={hint="Tuer 10 Tanneurs crins-pâles, 8 Ecorcheurs crins-pâles et 5 Braconniers crins-pâles, puis retourner voir Baine Sabot-de-Sang, à Sabot-de-Sang."}, [65]={hint="Collecter 5 Piolets de prospecteur."}, [66]={hint="Consommer l'Eau des Prophètes devant le feu tribal, à Sabot-de-Sang et suivre la vision quand elle apparaîtra.", desc="Bois l'Eau des Prophètes devant le feu de camp de la tribu, puis suis la vision vers le nord-ouest. Fais en chemin les quêtes déjà prises."}, [67]={npc="Périth Sabot-tempête", tgt="Périth Sabot-tempête", tag="Facultatif", desc="Pour éviter d'aller trop tôt aux Pitons-du-Tonnerre, prends la quête et fais l'escorte maintenant. Rends-la à ta première visite des Pitons-du-Tonnerre."}, [68]={hint="Aidez Périth Sabot-tempête à fuir le rocher des Crins-pâles, et allez aux Pitons-du-Tonnerre pour informer Cairne Sabot-de-Sang que Périth est sain et sauf.", tag="Facultatif"}, [69]={npc="Prophète Wiserunner", tgt="Prophète Wiserunner"}, [70]={npc="Prophète Wiserunner", tgt="Prophète Wiserunner"}, [71]={hint="Rapporter 6 Griffes de Traqueur et 6 Griffes de puma à Mull Thunderhorn."}, [72]={text="Utilise ta pierre de foyer pour revenir à Sabot-de-Sang et rends d'un coup les quêtes de l'ouest."}, [73]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [74]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [75]={npc="Maur Raincaller", tgt="Maur Raincaller"}, [76]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [77]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [78]={hint="Ahab Sabot-de-Blé, à Sabot-de-Sang en Mulgore, veut que vous nourrissiez son précieux chiot, Kyle le Frénétique.", tag="Facultatif", desc="Prépare un morceau de Viande de trotteur tendre, puis attends que Kyle s'approche pour le nourrir."}, [79]={npc="Ahab Sabot-de-Blé", tgt="Ahab Sabot-de-Blé", tag="Facultatif"}, [80]={text="Puits du nord, pierres rouges et mine du nord-est"}, [81]={hint="Utilisez le Totem de purification de Thunderhorn au puits Thunderhorn, puis retournez voir Mull."}, [82]={hint="Voyager aux Rochers rouges, à l'est de Thunder Bluff et parler à Esprit ancestral."}, [83]={npc="Gardien du savoir Raintotem", tgt="Gardien du savoir Raintotem"}, [84]={hint="Le Gardien du savoir Raintotem veut que vous tuiez 8 Intrus Dos-hirsute aux Rochers rouges."}, [85]={hint="Apporter 8 Serres de Furie-des-vents à Ruul Eagletalon, à Sabot-de-Sang."}, [86]={npc="Esprit ancestral", tgt="Esprit ancestral"}, [87]={npc="Gardien du savoir Raintotem", tgt="Gardien du savoir Raintotem"}, [88]={npc="Esprit ancestral", tgt="Esprit ancestral"}, [89]={hint="Tuez 6 Centaures galak et 4 estafettes galak, puis apportez la tête d'Herak le Pilleur à Baine Sabot-de-Sang."}, [90]={hint="Tuer 14 Travailleurs de la KapitalRisk et 6 Superviseurs de la KapitalRisk pour Morin Cloudstalker de Sabot-de-Sang."}, [91]={hint="Tuer le Superviseur Fizsprocket et rapporter son Ecritoire à Morin Cloudstalker, à Sabot-de-Sang."}, [92]={npc="Plans d'expansion de Mulgore", npcObj=true, tag="Facultatif", desc="Prends les Plans d'expansion de Mulgore sur le Superviseur Fizsprocket pour lancer la quête."}, [93]={hint="Récupérez les pages du superviseur Vibrouage se trouvant encore à l'intérieur de la mine de la KapitalRisk, et apportez-les à Morin Traqueur-de-Nuage, près de Sabot-de-Sang.", tag="Facultatif", desc="Récupère les trois notes à l'intérieur de la mine de la KapitalRisk avant de partir."}, [94]={hint="Abattez Chakuyak, puis rapportez sa fourrure.", tag="Facultatif"}, [95]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [96]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [97]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Facultatif"}, [98]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Facultatif", desc="En dessous du niveau 12? Fais d'autres quêtes près de la mine."}, [99]={hint="Apportez la clé de déboiseur à Morin Traqueur-de-Nuage, à l'extérieur de Sabot-de-Sang.", tag="Facultatif", desc="En dessous du niveau 12? Fais d'autres quêtes près de la mine."}, [100]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Facultatif", desc="En dessous du niveau 12? Fais d'autres quêtes près de la mine."}, [101]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [102]={npc="Ruul Eagletalon", tgt="Ruul Eagletalon"}, [103]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Facultatif"}, [104]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [105]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [106]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Facultatif"}, [107]={hint="Apporter 8 Dents de loup alpha des prairies à Mull Thunderhorn, à Sabot-de-Sang.", tag="Facultatif"}, [108]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Facultatif"}, [109]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Facultatif"}, [110]={hint="Utiliser le Totem de purification de Wildmane au puits Wildmane, puis retournez voir Mull Thunderhorn.", tag="Facultatif"}, [111]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Facultatif"}, [112]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Facultatif"}, [113]={npc="Skorn Whitecloud", tgt="Skorn Whitecloud", tag="Facultatif"}, [114]={hint="Apporter 4 Griffes de Rôdeurs des basses plaines à Melor Stonehoof à Thunder Bluff.", tag="Facultatif"}, [115]={text="Point de vol des Pitons-du-Tonnerre, puis direction La Croisée"}, [116]={text="Suis la route principale de Mulgore jusqu'aux Pitons-du-Tonnerre. Prends l'ascenseur et apprends le point de vol de Tal (47.00, 49.83)."}, [117]={hint="Parler à Cairne Sabot-de-Sang à Thunder Bluff."}, [118]={hint="Sollicitez une audience auprès de Cairne Sabot-de-Sang aux Pitons-du-Tonnerre."}, [119]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof"}, [120]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof"}, [121]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof", tag="Facultatif"}, [122]={hint="Apportez le rapport de Corne-Tonnerre à l'archidruide Hamuul Totem-Runique, aux Pitons-du-Tonnerre.", tag="Facultatif"}, [123]={npc="Archidruide Hamuul Runetotem", tgt="Archidruide Hamuul Runetotem", tag="Facultatif"}, [124]={npc="Melor Stonehoof", tgt="Melor Stonehoof", tag="Facultatif"}, [125]={npc="Eylah Cornesol", tgt="Eylah Cornesol", tag="Facultatif", desc="Achète les quatre matériaux sur la falaise. Utilise l'encens à la Cime des Chasseurs."}, [126]={hint="Achetez un paquet d'herbes à Nida l'herboriste, un fagot de brindilles de cèdre à Nata la fournisseuse de composants d'enchantements, des fibres tendineuses à Mahu le fournisseur de matériel de travail du cuir, ainsi que du silex et de l'amadou de cérémonie à Naal le fournisseur de matériel de cuisine.", tag="Facultatif", desc="Achète les quatre matériaux sur la falaise. Utilise l'encens à la Cime des Chasseurs."}, [127]={npc="Eylah Cornesol", tgt="Eylah Cornesol", tag="Facultatif", desc="Achète les quatre matériaux sur la falaise. Utilise l'encens à la Cime des Chasseurs."}, [128]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Facultatif", desc="Tu dois avoir appris le Dépeçage. Rends 12 cuirs légers."}, [129]={hint="Apporter 12 pièces de Cuir léger à Veren Tallstrider, à Thunder Bluff.", tag="Facultatif", desc="Tu dois avoir appris le Dépeçage. Rends 12 cuirs légers. Va à Thunder Bluff pour la remise. Le Cuir léger s'obtient en dépeçant des bêtes de bas niveau ou par échange."}, [130]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Facultatif", desc="Tu dois avoir appris le Dépeçage. Rends 12 cuirs légers."}, [131]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Facultatif", desc="Il faut connaître le Travail du cuir et avoir le niveau requis. Apporte 4 Cuirs légers et 4 Bobines de fil grossier."}, [132]={text="Bobine de fil grossier", npc="Mahu", tag="Facultatif"}, [133]={hint="Apporter 4 pièces de Cuir léger et 4 Bobines de fil grossier à Veren Tallstrider, à Thunder Bluff.", tag="Facultatif", desc="Il faut connaître le Travail du cuir et avoir le niveau requis. Apporte 4 Cuirs légers et 4 Bobines de fil grossier. Va à Thunder Bluff pour la remise. Le Cuir léger s'obtient par dépeçage ou par échange; achète la Bobine de fil grossier chez un marchand."}, [134]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Facultatif", desc="Il faut connaître le Travail du cuir et avoir le niveau requis. Apporte 4 Cuirs légers et 4 Bobines de fil grossier. Tu peux aussi prendre la quête auprès de Boramu (44.08, 44.89)."}, [135]={text="Au niveau 12, quitte Mulgore par la porte est et entre dans les Tarides. En passant par le Camp Taurajo, apprends le point de vol d'Omusa Thunderhorn (44.45, 59.15)."}, [136]={npc="Kirge Sternhorn", tgt="Kirge Sternhorn", tag="Facultatif", desc="Prends la quête en passant par le Camp Taurajo. Ta destination est La Croisée."}, [137]={hint="Parler à Thork, à la Croisée des Tarides.", tag="Facultatif", desc="Prends la quête en passant par le Camp Taurajo. Ta destination est La Croisée."}, [138]={npc="Thork", tgt="Thork", tag="Facultatif", desc="Prends la quête en passant par le Camp Taurajo. Ta destination est La Croisée."}, [139]={npc="Narm Skychaser", tgt="Narm Skychaser", desc="Commence au Village de Sabot-de-Sang. Poursuis les quêtes de chaman L'appel du feu→L'appel du feu à la Croisée, dans les Tarides. Tu peux aussi les prendre directement auprès de Kranal."}, [140]={hint="Trouver Kranal Fiss dans les Tarides.", desc="Commence au Village de Sabot-de-Sang. Poursuis les quêtes de chaman L'appel du feu→L'appel du feu à la Croisée, dans les Tarides. Tu peux aussi les prendre directement auprès de Kranal."}, [141]={npc="Kranal Fiss", tgt="Kranal Fiss", desc="Commence au Village de Sabot-de-Sang. Poursuis les quêtes de chaman L'appel du feu→L'appel du feu à la Croisée, dans les Tarides. Tu peux aussi les prendre directement auprès de Kranal."}, [142]={npc="Kary Thunderhorn", tgt="Kary Thunderhorn", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès d'Yaw Sharpmane."}, [143]={hint="Parler à Yaw Sharpmane, au village Bloodhoof.", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès d'Yaw Sharpmane."}, [144]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès d'Yaw Sharpmane."}, [145]={npc="Sian'dur", tgt="Sian'dur", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès d'Yaw Sharpmane."}, [146]={hint="Parler à Yaw Sharpmane, au village Bloodhoof.", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès d'Yaw Sharpmane."}, [147]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès d'Yaw Sharpmane."}, [148]={npc="Thotar", tgt="Thotar", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès d'Yaw Sharpmane."}, [149]={hint="Parler à Yaw Sharpmane, à Sabot-de-Sang.", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès d'Yaw Sharpmane."}, [150]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Dompter la bête directement auprès d'Yaw Sharpmane."}, [151]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [152]={hint="Utiliser le Bâtonnet de domptage pour dompter un trotteur des plaines adulte. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang."}, [153]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [154]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [155]={hint="Utiliser le Bâtonnet de domptage pour dompter un Traqueur des prairies. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang."}, [156]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [157]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [158]={hint="Utiliser le Bâtonnet de domptage pour dompter un Rapace. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang."}, [159]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [160]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", desc="Après les trois dressages, apprends les compétences de familier à la Cime des Chasseurs, aux Pitons-du-Tonnerre."}, [161]={hint="Parler à Holt Thunderhorn, sur la Cime des Chasseurs, à Thunder Bluff.", desc="Après les trois dressages, apprends les compétences de familier à la Cime des Chasseurs, aux Pitons-du-Tonnerre."}, [162]={npc="Holt Thunderhorn", tgt="Holt Thunderhorn", desc="Après les trois dressages, apprends les compétences de familier à la Cime des Chasseurs, aux Pitons-du-Tonnerre."}, [163]={npc="Gennia Runetotem", tgt="Gennia Runetotem", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Reflet-de-Lune directement auprès de Turak Runetotem."}, [164]={hint="Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Reflet-de-Lune directement auprès de Turak Runetotem."}, [165]={npc="Turak Runetotem", tgt="Turak Runetotem", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Reflet-de-Lune directement auprès de Turak Runetotem."}, [166]={npc="Pala l'aubergiste", tgt="Pala l'aubergiste", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Reflet-de-Lune directement auprès de Turak Runetotem."}, [167]={hint="Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Reflet-de-Lune directement auprès de Turak Runetotem."}, [168]={npc="Turak Runetotem", tgt="Turak Runetotem", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Reflet-de-Lune directement auprès de Turak Runetotem."}, [169]={npc="Gryshka l'aubergiste", tgt="Gryshka l'aubergiste", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Reflet-de-Lune directement auprès de Turak Runetotem."}, [170]={hint="Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Reflet-de-Lune directement auprès de Turak Runetotem."}, [171]={npc="Turak Runetotem", tgt="Turak Runetotem", tag="Facultatif", desc="Fais l'une des trois introductions ou prends Reflet-de-Lune directement auprès de Turak Runetotem."}, [172]={npc="Turak Runetotem", tgt="Turak Runetotem", desc="Apprends la téléportation auprès de Turak Runetotem, puis utilisez-la pour atteindre Reflet-de-Lune."}, [173]={hint="Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit.", desc="Apprends la téléportation auprès de Turak Runetotem, puis utilisez-la pour atteindre Reflet-de-Lune."}, [174]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Apprends la téléportation auprès de Turak Runetotem, puis utilisez-la pour atteindre Reflet-de-Lune."}, [175]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Parle à l'Esprit du Grand ours au nord-ouest, puis retourne à Havrenuit."}, [176]={hint="Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.", desc="Parle à l'Esprit du Grand ours au nord-ouest, puis retourne à Havrenuit."}, [177]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Parle à l'Esprit du Grand ours au nord-ouest, puis retourne à Havrenuit."}, [178]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [179]={hint="Retourner à Thunder Bluff, et parler à Turak Runetotem, sur la Cime des Anciens."}, [180]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [181]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [182]={hint="Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu'il possède."}, [183]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [184]={text="Suis la route vers le nord jusqu'à La Croisée. Apprends le point de vol de Devrak (51.50, 30.34) et lie ta pierre de foyer auprès de Boorand Plainswind l'aubergiste (51.99, 29.89)."}}},
    ["01-5"] = {name="Le Glas", tips={{k="交通", text="Si tu viens d'une autre zone de départ, descends à la tour des zeppelins au sud de Brill et suis la route vers l'ouest jusqu'au Glas. Trajet complet en haut de page."}, {k="提醒", text="Commence par Réveil brutal dans la crypte (morts-vivants uniquement). À ton arrivée au Glas, prends Les Déchus auprès du prêtre des ombres Sarvis (30.84, 66.20). Si Sarvis ne propose pas la quête, suis la route jusqu'à Brill.", s={{"Commence par Réveil brutal dans la crypte (morts-vivants uniquement)", {race={"Scourge"}}}, {"À ton arrivée au Glas, prends Les Déchus auprès du prêtre des ombres Sarvis (30.84, 66.20)"}, {"Si Sarvis ne propose pas la quête, suis la route jusqu'à Brill"}}}, {k="提醒", text="Si tu n'es pas encore niveau 3, tue encore quelques squelettes. Attends le niveau 3 pour prendre La dernière volonté de Marla. Va à Brill au niveau 6 ou une fois cette étape terminée.", s={{"Si tu n'es pas encore niveau 3, tue encore quelques squelettes"}, {"Attends le niveau 3 pour prendre La dernière volonté de Marla"}, {"Va à Brill au niveau 6 ou une fois cette étape terminée"}}}}, danger={[1]="Dans l'étroit tunnel des grottes des Tisse-nuit, tu risques d'attirer des araignées devant et derrière toi. Dégage l'entrée avant d'entrer."}, grind={[1]={mob="Zombie décharné", note="Des foules normales denses, pour la plupart neutres, au nord du Glas. Tire-les une par une pendant Les Déchus aux niveaux 1 et 2."}, [2]={mob="Araignée Tisse-nuit", note="Des foules normales denses dans les grottes des Tisse-nuit. Dégage par étapes depuis l'entrée pour éviter d'en tirer d'autres."}, [3]={mob="Initié écarlate", note="Des foules normales denses dans le camp écarlate oriental. Dégage le long du bord pour éviter de tirer les fanatiques. Associe-le à la quête du brassard."}}, supply={[1]={npc="Forgeron Rand"}, [2]={npc="Joshua Kien"}, [3]={npc="Joshua Kien"}}, steps={[1]={npc="Fossoyeur Mordo", tgt="Fossoyeur Mordo"}, [2]={hint="Parler au prêtre des ombres Sarvis."}, [3]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [4]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [5]={hint="Le prêtre des ombres Sarvis veut que vous tuiez 8 Zombies lunatiques et 8 Zombies décharnés."}, [6]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [7]={npc="Novice Elreth", tgt="Novice Elreth"}, [8]={hint="La novice Elreth a besoin de 6 Pattes de charognard et de 6 Ailes de chauve-souris du crépuscule."}, [9]={npc="Novice Elreth", tgt="Novice Elreth"}, [10]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [11]={npc="Garde noir Saltain", tgt="Garde noir Saltain"}, [12]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [13]={npc="Novice Elreth", tgt="Novice Elreth"}, [14]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel"}, [15]={hint="Tuez 12 Squelettes Cliquethorax, puis retournez voir le prêtre des ombres Sarvis au Glas."}, [16]={hint="Fouiller Le Glas et ses alentours pour trouver 6 pièces de fournitures de récupération, et les ramener au Garde noir Saltain."}, [17]={hint="L'Exécuteur Arren veut que vous tuiez 10 Jeunes Tisse-nuit et 8 Araignées Tisse-nuit."}, [18]={hint="Apporter le Cadavre de Samuel Fipps sur la Tombe de Marla, puis retourner voir la novice Elreth."}, [19]={hint="Libérez 6 victimes entoilées dans la grotte des tisse-nuit pour Aramis Mainmartel, au Glas."}, [20]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [21]={npc="Garde noir Saltain", tgt="Garde noir Saltain"}, [22]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [23]={npc="Novice Elreth", tgt="Novice Elreth"}, [24]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel"}, [25]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [26]={hint="Apporter à l'Exécuteur Arren 12 Bracelets écarlates, que vous trouverez sur des Convertis écarlates et des Initiés écarlates."}, [27]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [28]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [29]={hint="Tuer Meven Korgal, le messager, au camp de la Croisade, puis ramener toutes les informations trouvées à l'Exécuteur Arren."}, [30]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [31]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [32]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis", desc="Rends d'abord Les Déchus au Glas, dans les Clairières de Tirisfal. Tu peux aussi prendre la quête auprès de Novice Elreth (30.86, 66.05)."}, [33]={hint="Lisez le parchemin consacré et parlez à Aramis Mainmartel, dans l'église du Glas.", desc="Rends d'abord Les Déchus au Glas, dans les Clairières de Tirisfal."}, [34]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Rends d'abord Les Déchus au Glas, dans les Clairières de Tirisfal."}, [35]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Rends d'abord Les Déchus. Termine-la au Glas avant de partir."}, [36]={hint="Soignez 5 nécrogardes blessés avec votre technique Lumière sacrée.", desc="Rends d'abord Les Déchus. Termine-la au Glas avant de partir."}, [37]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Rends d'abord Les Déchus. Termine-la au Glas avant de partir."}, [38]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Remets d'abord Redécouverte de la Lumière."}, [39]={hint="Trouvez la paladine effrayée au Glas.", desc="Remets d'abord Redécouverte de la Lumière."}, [40]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Remets d'abord Redécouverte de la Lumière."}, [41]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Prends-la avant de quitter le Glas. Rends-la à ton arrivée à Brill."}, [42]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis", desc="Termine Les Déchus, puis prends la quête d'introduction auprès du maître de classe."}, [43]={hint="Lire le Parchemin simple, et parler à Dannal Stern, au Glas.", desc="Termine Les Déchus, puis prends la quête d'introduction auprès du maître de classe."}, [44]={npc="Dannal Stern", tgt="Dannal Stern", desc="Termine Les Déchus, puis prends la quête d'introduction auprès du maître de classe."}, [45]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis", desc="Termine Les Déchus, puis prends la quête d'introduction auprès du maître de classe."}, [46]={hint="Lire le Parchemin codé, et parler à David Trias, au Glas.", desc="Termine Les Déchus, puis prends la quête d'introduction auprès du maître de classe."}, [47]={npc="David Trias", tgt="David Trias", desc="Termine Les Déchus, puis prends la quête d'introduction auprès du maître de classe."}, [48]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [49]={hint="Lire le Rouleau contaminé, et parler à Maximillion, au Glas."}, [50]={npc="Maximillion", tgt="Maximillion"}, [51]={npc="Venya Marthand", tgt="Venya Marthand", desc="Voie du Glas. La quête est ouverte aux démonistes de la Horde."}, [52]={hint="Apporter 3 Crânes de Cliquethorax à Venya Marthand.", desc="Voie du Glas. La quête est ouverte aux démonistes de la Horde."}, [53]={npc="Venya Marthand", tgt="Venya Marthand", desc="Voie du Glas. La quête est ouverte aux démonistes de la Horde."}, [54]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis", desc="Remets Les Déchus pour déverrouiller le parchemin."}, [55]={hint="Lire le Parchemin béni, et parler au sombre clerc Duesten, dans l'église du Glas.", desc="Remets Les Déchus pour déverrouiller le parchemin."}, [56]={npc="Sombre clerc Duesten", tgt="Sombre clerc Duesten", desc="Remets Les Déchus pour déverrouiller le parchemin."}, [57]={npc="Sombre clerc Duesten", tgt="Sombre clerc Duesten"}, [58]={hint="Parler au sombre clerc Beryl dans les Clairières de Tirisfal."}, [59]={npc="Sombre clerc Beryl", tgt="Sombre clerc Beryl"}, [60]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis", desc="Remets d'abord Les Déchus."}, [61]={hint="Lire le Parchemin glyphé, et parler à Isabella, dans l'église du Glas.", desc="Remets d'abord Les Déchus."}, [62]={npc="Isabella", tgt="Isabella", desc="Remets d'abord Les Déchus."}, [63]={text="Prends la route est en sortant du Glas jusqu'à Brill."}}},
    ["01-6"] = {name="Clairières de Tirisfal", nameA="Clairières de Tirisfal: {a:159}", tips={{k="提醒", text="Si tu n'as pas pris Informations décisives, commence à l'auberge de Brill et prends le premier lot de quêtes.", s={{"Si tu n'as pas pris Informations décisives, commence à l'auberge de Brill et prends le premier lot de quêtes"}}}, {k="取捨", text="Fais les objectifs écarlates, araignées et Herbes sépulcrales d'une traite au sud-est. Regroupe les murlocs de la côte nord avec les quêtes d'Agamand. Rends les quêtes à proximité et pars pour La Croisée au niveau 12."}, {k="取捨", text="Pour Le Frisson de la mort près de l'auberge, achète des Bobines de fil grossier auprès d'un vendeur. S'il te manque encore des peaux de murlocs de la côte nord pour Des peaux pour les Réprouvés, termine-la lors de ton prochain passage sur la côte."}, {k="取捨", text="Après les deux quêtes locales de l'Aube d'argent, tu peux prendre La forteresse de Bandarion (Orcs, Trolls et Morts-vivants uniquement). Certaines suites sont réservées aux Morts-vivants. Si tu files vers La Croisée, tu peux partir après les deux quêtes locales.", s={{"Après les deux quêtes locales de l'Aube d'argent, tu peux prendre La forteresse de Bandarion (Orcs, Trolls et Morts-vivants uniquement)", {race={"Orc", "Troll", "Scourge"}}}, {"Certaines suites sont réservées aux Morts-vivants", {race={"Scourge"}}}, {"Si tu files vers La Croisée, tu peux partir après les deux quêtes locales"}}}, {k="提醒", text="En dessous du niveau 12? Fais en priorité En Guerre avec la Croisade écarlate, La Crypte Familiale ou les quêtes de l'Aube d'argent L'émissaire de l'Aube d'argent, Le Culte des damnés et Les vestiges de la guerre, selon ce qui est disponible et là où tu te trouves.", s={{"En dessous du niveau 12?"}, {"Fais en priorité En Guerre avec la Croisade écarlate, La Crypte Familiale ou les quêtes de l'Aube d'argent L'émissaire de l'Aube d'argent, Le Culte des damnés et Les vestiges de la guerre, selon ce qui est disponible et là où tu te trouves"}}}}, danger={[1]="Dans le cimetière sud-est, des zombies de sang et des fantômes errants peuvent t'attaquer des deux côtés. Dégage le long du bord et garde une issue de repli."}, grind={[1]={mob="Missionnaire écarlate", note="Des foules normales éparses au sud-ouest de Brill, avec des lanceurs de sorts. Tire-les une par une depuis le bord du camp pendant les premières quêtes de la Croisade écarlate."}, [2]={mob="Esprit vagabond", note="Des foules normales se regroupent avec les zombies de sang dans le cimetière sud-est. Surveille les patrouilles. Fais Patrouille d'arrière-garde en même temps que la quête des Herbes sépulcrales."}, [3]={mob="Néophyte sombre", note="Des foules normales denses près des quêtes de l'Aube d'argent au sud-est. Tire-les une par une depuis le bord du camp pour éviter les Dark Enforcers. Farme du niveau 11 au niveau 12."}}, supply={[1]={npc="Renée l'aubergiste"}, [2]={npc="Abe Winters"}, [3]={npc="Renée l'aubergiste"}, [4]={npc="Mme Winters"}, [5]={npc="Doras"}}, steps={[1]={npc="Garde noir Simmer", tgt="Garde noir Simmer"}, [2]={npc="Gordo", tgt="Gordo"}, [3]={hint="Volez 10 Potirons dans la ferme à l'ouest, juste au nord du Glas, et apportez-les à l'Apothicaire Johaan à Brill."}, [4]={hint="Récolter 3 herbes des ténèbres et les apporter à l'Apprenti Apothicaire Holland au cimetière de Brill."}, [5]={hint="Livrer les documents de la Croisade écarlate à l'Exécuteur Zygand à Brill."}, [6]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [7]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [8]={npc="Apprenti apothicaire Holland", tgt="Apprenti apothicaire Holland"}, [9]={text="Lie ta pierre de foyer auprès de Renée l'aubergiste à Brill (61.72, 52.05)."}, [10]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [11]={hint="Donner la citrouille enchantée au Zélote écarlate capturé qui est gardé dans le cellier de la taverne des Pendus."}, [12]={npc="Zélote écarlate capturé", tgt="Zélote écarlate capturé"}, [13]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger"}, [14]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [15]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [16]={npc="Apprenti apothicaire Holland", tgt="Apprenti apothicaire Holland"}, [17]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [18]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [19]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [20]={npc="Recherché !", npcObj=true}, [21]={text="Autour de Brill et camp de la Croisade écarlate à l'ouest"}, [22]={hint="Rapporter 7 Griffes putrides au Garde noir Dillinger à Brill."}, [23]={hint="Tuer des Profanateurs Poils-putrides et des Gnolls Poils-putrides."}, [24]={hint="Collecter 5 fioles de Sang de sombredogues pour l'Apothicaire Johaan de la ville de Brill."}, [25]={hint="Récolter 10 Herbes maléfiques et les apporter à l'apprenti apothicaire Holland."}, [26]={hint="Tuer 10 Guerriers écarlates pour l'Exécuteur Zygand."}, [27]={hint="Punissez 5 nécrogardes pour l'exécuteur Zygand."}, [28]={hint="Obtenez les rapports des nécrogardes Dillinger et Kristof et de Gordo pour l'exécuteur Zygand."}, [29]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger"}, [30]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [31]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [32]={npc="Apprenti apothicaire Holland", tgt="Apprenti apothicaire Holland"}, [33]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [34]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [35]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [36]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger"}, [37]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [38]={npc="Garde noir Burgess", tgt="Garde noir Burgess"}, [39]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [40]={npc="Apprenti apothicaire Holland", tgt="Apprenti apothicaire Holland"}, [41]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [42]={text="Murlocs de la côte nord, Œil-de-ver et Moulins d'Agamand"}, [43]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [44]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [45]={npc="Gretchen Dedmar", tgt="Gretchen Dedmar"}, [46]={hint="L'Apothicaire Johaan de la ville de Brill a besoin de 5 Ecailles d'Aileron noir prises sur les murlocs des Clairières de Tirisfal."}, [47]={hint="Tuer Œil-de-ver et rapporter ses griffes à l'Exécuteur Zygand pour toucher la récompense."}, [48]={hint="Rassemblez 5 Côtes ébréchées et 3 Crânes noircis et rapportez-les au garde noir Dillinger à Brill."}, [49]={hint="Rapporter les restes de Gregor, de Nissa et de Thurman à Coleman Farthing, à Brill."}, [50]={hint="Tuer Devlin Agamand et ramener ses restes à Coleman Farthing à Brill."}, [51]={npc="Une lettre pour Yvette", npcObj=true, tag="Facultatif"}, [52]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [53]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [54]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger"}, [55]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [56]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [57]={hint="Trouver Yvette Farthing. Lui donner la lettre de Thurman Agamand.", tag="Facultatif"}, [58]={npc="Yvette Farthing", tgt="Yvette Farthing", tag="Facultatif"}, [59]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [60]={hint="Parler au magistrat Sevren à Brill."}, [61]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [62]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [63]={text="Camp écarlate du sud, avant-poste sud-est et Ferme des Balnir"}, [64]={hint="Tuer le capitaine Perrine ainsi que 3 Zélotes écarlates et 3 Missionnaires écarlates."}, [65]={hint="Parler à la Garde noire Linnea."}, [66]={npc="Garde noir Linnea", tgt="Garde noir Linnea"}, [67]={npc="Garde noir Linnea", tgt="Garde noir Linnea"}, [68]={npc="Garde noir Linnea", tgt="Garde noir Linnea"}, [69]={npc="Shelene Rhobart", tgt="Shelene Rhobart", tag="Facultatif", desc="Tu peux aussi prendre la quête auprès de Garde noir Linnea (65.49, 60.25)."}, [70]={hint="Tuer 8 Horreurs sanguinolentes et 8 Esprits vagabonds, puis revenez voir Linnea, à son camp."}, [71]={hint="Récoltez 5 herbes sépulcrales et apportez-les à l'apprenti apothicaire Holland."}, [72]={hint="L'Apothicaire Johaan de la ville de Brill désire que vous lui rameniez 4 échantillons de Venin de Tisse-nuit vicieuse."}, [73]={text="Bobine de fil grossier", npc="Abigail Shiel"}, [74]={hint="Rapporter 5 Peaux de chauve-souris du crépuscule et une Bobine de fil grossier à Gretchen Dedmar à Brill."}, [75]={npc="Garde noir Linnea", tgt="Garde noir Linnea"}, [76]={hint="Retourner voir le Magistrat Sevren à Brill."}, [77]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [78]={npc="Apprenti apothicaire Holland", tgt="Apprenti apothicaire Holland"}, [79]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [80]={npc="Gretchen Dedmar", tgt="Gretchen Dedmar"}, [81]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [82]={hint="Apporter la Boisson spéciale de Johaan au Montagnard captif."}, [83]={npc="Montagnard capturé", tgt="Montagnard capturé"}, [84]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [85]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [86]={hint="Apportez à Shelene Rhobart 8 membranes d'ailes de chauve-souris de la pénombre, 6 peaux de sombredogue et 3 peaux de Murloc aileron noir.", tag="Facultatif"}, [87]={npc="Shelene Rhobart", tgt="Shelene Rhobart", tag="Facultatif"}, [88]={hint="L'Exécuteur Zygand de Brill vous a chargé de liquider le capitaine Vachon et 5 Frères écarlates."}, [89]={hint="Apporter 10 Anneaux de la Croisade écarlate au Garde noir Burgess à Brill."}, [90]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [91]={npc="Garde noir Burgess", tgt="Garde noir Burgess"}, [92]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand", tag="Facultatif", desc="Le plus éloigné du village. N'y vas que si tu es encore en dessous du niveau 12."}, [93]={hint="Assassiner le capitaine Melrach et ses deux gardes du corps pour l'Exécuteur Zygand de la ville de Brill.", tag="Facultatif", desc="Le plus éloigné du village. N'y vas que si tu es encore en dessous du niveau 12."}, [94]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand", tag="Facultatif", desc="Le plus éloigné du village. N'y vas que si tu es encore en dessous du niveau 12."}, [95]={npc="Magistrat Sevren", tgt="Magistrat Sevren", tag="Facultatif", desc="Accepte une fois les deux quêtes Agamand terminées.", star={"Bâton de sombrebois", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}}, [96]={hint="Tuer 8 Spectres ancestraux et 8 Ancêtres pourrissants.", tag="Facultatif", desc="Accepte une fois les deux quêtes Agamand terminées."}, [97]={npc="Magistrat Sevren", tgt="Magistrat Sevren", tag="Facultatif", desc="Accepte une fois les deux quêtes Agamand terminées.", star={"Bâton de sombrebois", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}}, [98]={text="XP supplémentaire ou nouvelles quêtes avant le niveau 12"}, [99]={npc="Garde noir Terrence", tgt="Garde noir Terrence", tag="Facultatif"}, [100]={hint="Trouvez le membre de l'Aube d'argent près de l'entrée de Fossoyeuse.", tag="Facultatif"}, [101]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif"}, [102]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif"}, [103]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif"}, [104]={hint="Tuez 8 néophytes sombres et 8 massacreurs sombres dans les clairières de Tirisfal.", tag="Facultatif"}, [105]={hint="Rassemblez 12 fragments de cristal nécrotique dans les clairières de Tirisfal.", tag="Facultatif"}, [106]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif"}, [107]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif"}, [108]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif", desc="Ça t'éloigne de l'avant-poste sud-est. Passe-la si tu es pressé."}, [109]={hint="Retrouvez Leonid Barthalomew à la forteresse de Bandarion, dans les clairières de Tirisfal.", tag="Facultatif", desc="Ça t'éloigne de l'avant-poste sud-est. Passe-la si tu es pressé."}, [110]={npc="Leonid Barthalomew le Révéré", tgt="Leonid Barthalomew le Révéré", tag="Facultatif", desc="Ça t'éloigne de l'avant-poste sud-est. Passe-la si tu es pressé."}, [111]={npc="Garde noir Linnea", tgt="Garde noir Linnea", tag="Facultatif", desc="Élite. Passe-la si tu es seul."}, [112]={hint="Apportez le cœur de Fendécorche à la nécrogarde Linnea.", tag="Facultatif", desc="Élite. Passe-la si tu es seul."}, [113]={npc="Garde noir Linnea", tgt="Garde noir Linnea", tag="Facultatif", desc="Élite. Passe-la si tu es seul."}, [114]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan", tag="Facultatif", desc="Rends-la quand tu pars pour la forêt des Pins argentés au niveau 16."}, [115]={hint="Suivez la route vers l'est à la sortie du Glas pour rejoindre le village de Brill. Présentez-vous à Shari Morpuits afin de poursuivre votre entraînement."}, [116]={npc="Shari Morpuits", tgt="Shari Morpuits"}, [117]={npc="Shari Morpuits", tgt="Shari Morpuits", desc="Prends-la quand tu reviens à Brill au niveau 8."}, [118]={hint="Trouvez la forteresse de Bandarion et présentez-vous devant Breton Samuels.", desc="Prends-la quand tu reviens à Brill au niveau 8."}, [119]={npc="Danitha Morr", tgt="Breton Samuels", desc="Prends-la quand tu reviens à Brill au niveau 8."}, [120]={npc="Danitha Morr", tgt="Breton Samuels", desc="Niveau 7 minimum. Fais-la lors de ton premier passage au fort, au niveau 8."}, [121]={hint="Tuez 8 attaquants aileron noir et 8 oracles aileron noir, puis retournez voir Breton Samuels une fois que c'est fait.", desc="Niveau 7 minimum. Fais-la lors de ton premier passage au fort, au niveau 8."}, [122]={npc="Danitha Morr", tgt="Breton Samuels", desc="Niveau 7 minimum. Fais-la lors de ton premier passage au fort, au niveau 8."}, [123]={npc="Danitha Morr", tgt="Breton Samuels", desc="Remets d'abord Des Murlocs à nos portes."}, [124]={hint="Parlez aux habitants la forteresse de Bandarion.", desc="Remets d'abord Des Murlocs à nos portes."}, [125]={npc="Danitha Morr", tgt="Danitha Morr", desc="Remets d'abord Des Murlocs à nos portes."}, [126]={npc="Jorin Croge", tgt="Jorin Croge", desc="Facultatif. Au niveau 9, faites cela dans Ombreval aux côtés de Les ternis."}, [127]={npc="Danitha Morr", tgt="Danitha Morr", desc="Rends d'abord En patrouille. Si tu as déjà pris Procéder aux réparations, fais-la en même temps que celle-ci."}, [128]={hint="Récupérez 12 morceaux de bois solides à Ombreval, dans les clairières de Tirisfal.", desc="Niveau 8 minimum. Ignore-la si elle est déjà terminée."}, [129]={hint="Tuez 8 manœuvres ternis et 6 zélotes ternis, puis récupérez la tête du commandant Rudolph Gelhardt dans les clairières de Tirisfal."}, [130]={npc="Jorin Croge", tgt="Jorin Croge", desc="Facultatif. Ignore-la si tu l'as déjà faite au niveau 8."}, [131]={npc="Danitha Morr", tgt="Danitha Morr"}, [132]={npc="Danitha Morr", tgt="Danitha Morr", desc="Rends d'abord Les ternis. Si tu approches du niveau 12, tu peux attendre ton premier passage à Fossoyeuse pour Rédemption (Une leçon de divinité) et tout rendre d'un coup."}, [133]={hint="Apportez la tête de Rudolph Gelhardt à Sylvanas Coursevent, à Fossoyeuse.", desc="Rends d'abord Les ternis. Si tu approches du niveau 12, tu peux attendre ton premier passage à Fossoyeuse pour Rédemption (Une leçon de divinité) et tout rendre d'un coup."}, [134]={npc="Dame Sylvanas Windrunner", tgt="Dame Sylvanas Windrunner", desc="Rends d'abord Les ternis. Si tu approches du niveau 12, tu peux attendre ton premier passage à Fossoyeuse pour Rédemption (Une leçon de divinité) et tout rendre d'un coup."}, [135]={npc="Danitha Morr", tgt="Danitha Morr", desc="Au niveau 12, après les quêtes du fort, va voir Danitha. Apporte 10 Étoffes de lin à Fossoyeuse."}, [136]={hint="Parlez à Tanis Aulnebois, à Fossoyeuse.", desc="Au niveau 12, après les quêtes du fort, va voir Danitha. Apporte 10 Étoffes de lin à Fossoyeuse."}, [137]={npc="Tanis Aulnebois", tgt="Tanis Aulnebois", desc="Au niveau 12, après les quêtes du fort, va voir Danitha. Apporte 10 Étoffes de lin à Fossoyeuse."}, [138]={npc="Tanis Aulnebois", tgt="Tanis Aulnebois"}, [139]={hint="Apporter 10 morceaux d'étoffe de lin à Tanis Aulnebois, à Fossoyeuse."}, [140]={npc="Tanis Aulnebois", tgt="Tanis Aulnebois"}, [141]={npc="Tanis Aulnebois", tgt="Tanis Aulnebois"}, [142]={hint="Retournez voir Danitha Morr, à la forteresse de Bandarion."}, [143]={npc="Danitha Morr", tgt="Danitha Morr"}, [144]={npc="Danitha Morr", tgt="Danitha Morr", desc="Si tu perds le Symbole de vie, demande-en un autre à Danitha Morr."}, [145]={hint="Parlez au nécrogarde Billmuth, à la forteresse de Bandarion .", desc="Si tu perds le Symbole de vie, demande-en un autre à Danitha Morr."}, [146]={npc="Nécrogarde Billmuth", tgt="Nécrogarde Billmuth", desc="Si tu perds le Symbole de vie, demande-en un autre à Danitha Morr."}, [147]={npc="Nécrogarde Billmuth", tgt="Nécrogarde Billmuth"}, [148]={hint="Prenez le Symbole de vie et utilisez-le pour ressusciter le nécrogarde Falgan dans la vallée de Tissevenin."}, [149]={npc="Nécrogarde Falgan", tgt="Nécrogarde Falgan"}, [150]={npc="Nécrogarde Falgan", tgt="Nécrogarde Falgan"}, [151]={hint="Dérobez les plans d'attaque de la Croisade écarlate aux croisés écarlates de la vallée de Tissevenin, puis retrouvez le nécrogarde Billmuth à la forteresse de Bandarion."}, [152]={npc="Nécrogarde Billmuth", tgt="Nécrogarde Billmuth"}, [153]={npc="Nécrogarde Billmuth", tgt="Nécrogarde Billmuth", desc="Apprends Rédemption après avoir validé la quête."}, [154]={hint="Parlez à Danitha Morr au donjon de la forteresse de Bandarion.", desc="Apprends Rédemption après avoir validé la quête."}, [155]={npc="Danitha Morr", tgt="Danitha Morr", desc="Apprends Rédemption après avoir validé la quête."}, [156]={npc="Austil de Mon", tgt="Austil de Mon", desc="Choisis cette chaîne ou Le vétéran Uzzek → La voie de la défense dans les Tarides."}, [157]={hint="Parler au Garde noir Dillinger à Brill.", desc="Choisis cette chaîne ou Le vétéran Uzzek → La voie de la défense dans les Tarides."}, [158]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger", desc="Choisis cette chaîne ou Le vétéran Uzzek → La voie de la défense dans les Tarides."}, [159]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger", desc="Élimine les foules près du cimetière avant de commencer l'événement."}, [160]={hint="Tuer Ulag le Fendeur, puis parler au Garde noire Dillinger.", desc="Élimine les foules près du cimetière avant de commencer l'événement."}, [161]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger", desc="Élimine les foules près du cimetière avant de commencer l'événement."}, [162]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger", tag="Facultatif", desc="Quête de récompense d'arme facultative."}, [163]={hint="Parler à Coleman Farthing.", tag="Facultatif", desc="Quête de récompense d'arme facultative."}, [164]={npc="Coleman Farthing", tgt="Coleman Farthing", tag="Facultatif", desc="Quête de récompense d'arme facultative."}, [165]={npc="Coleman Farthing", tgt="Coleman Farthing", tag="Facultatif", desc="Chacune des quatre armes a son propre conteneur."}, [166]={hint="Rapporter à Coleman Farthing la Hache de la famille Agamand, l'Epée de la famille Agamand, la Masse de la famille Agamand et la Dague de la famille Agamand.", tag="Facultatif", desc="Chacune des quatre armes a son propre conteneur."}, [167]={npc="Coleman Farthing", tgt="Coleman Farthing", tag="Facultatif", desc="Chacune des quatre armes a son propre conteneur."}, [168]={npc="Coleman Farthing", tgt="Coleman Farthing", tag="Facultatif", desc="Remets d'abord L'héritage des Agamand.", star={"Hache de l'héritier", {"WARRIOR"}}}, [169]={hint="Remplissez les objectifs de la quête.", tag="Facultatif", desc="Remets d'abord L'héritage des Agamand."}, [170]={npc="Coleman Farthing", tgt="Coleman Farthing", tag="Facultatif", desc="Remets d'abord L'héritage des Agamand.", star={"Hache de l'héritier", {"WARRIOR"}}}, [171]={npc="Marion Call", tgt="Marion Call"}, [172]={hint="Aller voir Mennet Carkad dans le Quartier des voleurs de Fossoyeuse."}, [173]={npc="Mennet Carkad", tgt="Mennet Carkad"}, [174]={npc="Mennet Carkad", tgt="Mennet Carkad", desc="La cible patrouille : repère d'abord son trajet, puis va à Fossoyeuse pour rendre la quête."}, [175]={hint="Trouver la Lettre de recommandation d'Astor et l'apporter à Mennet Carkad dans le Quartier des voleurs.", desc="Il patrouille : surveille la route. Parle-lui et choisis de le provoquer, sinon il ne combat pas."}, [176]={npc="Mennet Carkad", tgt="Mennet Carkad", desc="La cible patrouille : repère d'abord son trajet, puis va à Fossoyeuse pour rendre la quête."}, [177]={npc="Mennet Carkad", tgt="Mennet Carkad"}, [178]={hint="Aller voir Andron Gant à Fossoyeuse."}, [179]={npc="Andron Gant", tgt="Andron Gant"}, [180]={npc="Andron Gant", tgt="Andron Gant"}, [181]={hint="Apporter le Grand Livre d'Astor à Mennet Carkad dans le Quartier des voleurs de Fossoyeuse."}, [182]={npc="Mennet Carkad", tgt="Mennet Carkad"}, [183]={npc="Mennet Carkad", tgt="Mennet Carkad", star={"Lame de malice", {"ROGUE"}}}, [184]={hint="Livrer le Grand Livre d'Andron à Varimathras au Hall de la Dame noire à Fossoyeuse."}, [185]={npc="Varimathras", tgt="Varimathras", star={"Lame de malice", {"ROGUE"}}}, [186]={npc="Ageron Kargal", tgt="Ageron Kargal", tag="Facultatif", desc="Tu peux ignorer l'introduction. La quête est ouverte aux démonistes de la Horde."}, [187]={hint="Parler à Carendin Halgar à Fossoyeuse.", tag="Facultatif", desc="Tu peux ignorer l'introduction. La quête est ouverte aux démonistes de la Horde."}, [188]={npc="Carendin Halgar", tgt="Carendin Halgar", tag="Facultatif", desc="Tu peux ignorer l'introduction. La quête est ouverte aux démonistes de la Horde."}, [189]={npc="Carendin Halgar", tgt="Carendin Halgar", desc="Récupère le Grimoire d'Egalin dans la tour en ruine au sud de Brill."}, [190]={hint="Retrouver le Grimoire d'Egalin et l'apporter à Carendin Halgar au Temple des damnés.", desc="Récupère le Grimoire d'Egalin dans la tour en ruine au sud de Brill."}, [191]={npc="Carendin Halgar", tgt="Carendin Halgar", desc="Récupère le Grimoire d'Egalin dans la tour en ruine au sud de Brill."}, [192]={npc="Carendin Halgar", tgt="Carendin Halgar", desc="Utilise la rune sur le cercle d'invocation du Quartier de la magie et bats le Marcheur du Vide."}, [193]={hint="Utiliser les Runes d'invocation pour invoquer et soumettre un marcheur du Vide, puis rapporter les Runes d'invocation à Carendin Halgar, au Temple des Damnés.", desc="Utilise la rune sur le cercle d'invocation du Quartier de la magie et bats le Marcheur du Vide."}, [194]={npc="Carendin Halgar", tgt="Carendin Halgar", desc="Utilise la rune sur le cercle d'invocation du Quartier de la magie et bats le Marcheur du Vide."}, [195]={npc="Sombre clerc Beryl", tgt="Sombre clerc Beryl", desc="Entraîne d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [196]={hint="Trouver le Garde noir Kel et le guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir le sombre clerc Beryl, à Brill.", desc="Entraîne d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [197]={npc="Sombre clerc Beryl", tgt="Sombre clerc Beryl", desc="Entraîne d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [198]={npc="Aelthalyste", tgt="Aelthalyste"}, [199]={hint="Remplissez les objectifs de la quête."}, [200]={npc="Aelthalyste", tgt="Aelthalyste"}, [201]={npc="Cain Firesong", tgt="Cain Firesong"}, [202]={hint="Aller voir Anastasia Hartwell."}, [203]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell"}, [204]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell"}, [205]={hint="Apporter des Gueules-de-loup du jardin des Balnir à Anastasia Hartwell dans le Quartier de la magie de Fossoyeuse."}, [206]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell"}, [207]={text="Va à la tour des zeppelins au sud-est de Brill et monte à bord du zeppelin d'Orgrimmar sur la plate-forme ouest, auprès de Zapetta (60.74, 58.87). Descends à la plate-forme sud de la tour est, devant l'entrée d'Orgrimmar, à Durotar (50.82, 13.54)."}, [208]={text="Entre à Orgrimmar par la porte principale et apprends le point de vol de Doras (45.12, 63.89). Si le point de vol de La Croisée est débloqué, envole-toi directement. Sinon, descends vers le sud jusqu'à Tranchecolline par la grande route de Durotar, traverse le pont vers l'ouest dans les Tarides et continue jusqu'à La Croisée. Là, apprends le point de vol de Devrak (51.50, 30.34), lie ta pierre de foyer auprès de Boorand Plainswind l'aubergiste (51.99, 29.89) et prends les quêtes de La Croisée."}}},
    ["01-7"] = {tips={{k="交通", text="Si tu viens d'une autre zone de départ, prends le Skycutter au quai sud du Plateau de Guette-ciel, à Mulgore (34.30, 25.80). Descends au quai ouest de Valanaar (57.90, 80.90), puis suis la route vers le nord jusqu'au Bosquet de Thendal."}, {k="提醒", text="Depuis Valanaar, suis la grande route au nord jusqu'au Bosquet de Thendal. Les autres races de la Horde peuvent faire les quêtes secondaires communes. L'addon filtre les étapes réservées à certaines races et celles dont les prérequis manquent. Aux niveaux 1-3, tue les jeunes vuldrens et les cirrusflies près du bosquet avant les quêtes de collecte et du village. Si tu es encore sous le niveau 12 après les quêtes disponibles, termine au Village de Sabot-de-Sang en Mulgore.", s={{"Depuis Valanaar, suis la grande route au nord jusqu'au Bosquet de Thendal"}, {"Les autres races de la Horde peuvent faire les quêtes secondaires communes"}, {"L'addon filtre les étapes réservées à certaines races et celles dont les prérequis manquent"}, {"Aux niveaux 1-3, tue les jeunes vuldrens et les cirrusflies près du bosquet avant les quêtes de collecte et du village"}, {"Si tu es encore sous le niveau 12 après les quêtes disponibles, termine au Village de Sabot-de-Sang en Mulgore"}}}, {k="取捨", text="Suis la route principale de l'île : Bosquet de Thendal, Shen'dar, Valanaar, puis le sanctuaire d'Akir. En dessous du niveau 12? Fais d'abord les quêtes secondaires du verger ou de la forêt de Trombenoire, puis monte à bord du zeppelin."}, {k="取捨", text="Prends ensemble les quêtes de l'apprenti et du bandit près du village. Tu peux aussi ajouter Harceleurs hippogriffes si tu es Skyborne. Le problème avec les fièregriffes donne une Sacoche simple en cuir. Des mages perturbateurs propose l'Idole des flots changeants aux druides. L'appel du feu donne le Totem des flammes chargées aux chamans.", s={{"Prends ensemble les quêtes de l'apprenti et du bandit près du village"}, {"Tu peux aussi ajouter Harceleurs hippogriffes si tu es Skyborne", {race={"天裔精靈"}}}, {"Le problème avec les fièregriffes donne une Sacoche simple en cuir"}, {"Des mages perturbateurs propose l'Idole des flots changeants aux druides", {class={"DRUID"}}}, {"L'appel du feu donne le Totem des flammes chargées aux chamans", {class={"SHAMAN"}}}}}, {k="提醒", text="Les suites de l'île La suite des évènements et Le Cercle terrestre affichent le niveau 13 mais sont disponibles dès le niveau 7. Prends-les après la chaîne principale.", s={{"Les suites de l'île La suite des évènements et Le Cercle terrestre affichent le niveau 13 mais sont disponibles dès le niveau 7"}, {"Prends-les après la chaîne principale"}}}}, danger={[1]="Le saut depuis la tour de guet du Bosquet de Thendal demande Marche sur l'air. Place d'abord ce pouvoir racial sur ta barre d'action, puis utilise-le dès que tu as sauté.", [2]="Les Stormchasers d'Al'Aketh sont mêlés aux fantassins dans le camp de la forêt de Trombenoire. Évite le centre du camp et tire-les un par un depuis le bord."}, grind={[1]={mob="Jeune vuldrène", note="Des foules normales denses dans le Bosquet de Thendal. Tire-les une par une et surveille les essaims proches. Farme près du point de départ aux niveaux 1 et 2."}, [2]={mob="Bandit des hautes-terres", note="Des foules normales denses dans les hautes terres de Shen'dar. Tire les bandits depuis le bord du camp pour éviter les groupes. Fais-le en même temps que L'élément du crime et Les pierres de vent chapardées."}, [3]={mob="Chasse-tempêtes al'aketh", note="Des foules normales denses dans la forêt de Trombenoire. Tire-les depuis le bord pour éviter les fantassins. Fais-le en même temps qu'Indignes même dans la mort, ou farme jusqu'au niveau 12."}}, supply={[1]={npc="Fevrath Marteau-Céleste"}, [2]={npc="Uualia Solcrête"}, [3]={npc="Uualia Solcrête"}, [4]={npc="Citoyen de Zéphras"}, [5]={npc="Aedi Triple-Forgé"}, [6]={npc="Citoyen de Zéphras"}, [7]={npc="Belandiel Longvol"}, [8]={npc="Donaal Bassebrise"}, [9]={npc="Taliaa Brilleciel"}, [10]={npc="Donaal Bassebrise"}, [11]={npc="Antelariaa Mirenuée"}, [12]={npc="Tal"}}, steps={[1]={npc="Dalia la Collectionneuse", tgt="Ailee Cœur-Lointain"}, [2]={hint="Parlez à Rorian le Cherchejour dans le bosquet de Thendal."}, [3]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [4]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [5]={npc="Falorne Tombevent", tgt="Elatrell Frêleplume"}, [6]={npc="Myriaal Sillebrume", tgt="Myriaal Sillebrume"}, [7]={npc="Halaan Oeil-de-Faucon", tgt="Halaan Oeil-de-Faucon"}, [8]={hint="Éliminez 8 jeunes vuldrènes dans le bosquet de Thendal."}, [9]={hint="Éliminez 8 mouches-cirrus agaçantes dans le bosquet de Thendal."}, [10]={hint="Sautez du haut de la tour de guet du bosquet de Thendal et utilisez votre compétence Marche sur l'air pour ralentir votre chute.", desc="Monte sur la tour de guet, saute, puis active Marche sur l'air avant de toucher le sol."}, [11]={hint="Parlez à Halaan Œil-de-Faucon et empruntez son don pour observer le pylône d'ancrage au loin."}, [12]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [13]={npc="Falorne Tombevent", tgt="Elatrell Frêleplume"}, [14]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [15]={npc="Halaan Oeil-de-Faucon", tgt="Halaan Oeil-de-Faucon"}, [16]={npc="Falorne Tombevent", tgt="Elatrell Frêleplume"}, [17]={npc="Destin Triple-Forgé", tgt="Dalia la Collectionneuse"}, [18]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [19]={npc="Ventaari Vœu-Radieux", tgt="Ventaari Vœu-Radieux"}, [20]={hint="Détruisez la reine mouche-cirrus dans le bosquet de Thendal."}, [21]={hint="Récupérez 15 blocs de pierres de vent sur des pierres de vent brutes dans le bosquet de Thendal."}, [22]={hint="Utilisez votre compétence raciale Vue céleste à la convergence élémentaire dans le bosquet de Thendal.", desc="Utilise Vue céleste, le pouvoir racial des Skyborne, près de la Convergence élémentaire."}, [23]={npc="Falorne Tombevent", tgt="Elatrell Frêleplum