    [843] = {n="La réclamation de Gann", d="Gann Stonespire veut que vous tuiez 15 Excavateurs de Bael'dun et 5 Surveillants de Bael'dun.\nApporter le Journal de Khazgorm à Gann Stonespire.", tgo={{"Excavateur de Bael'dun"}, {"Contremaître de Bael'dun"}, {"Prospecteur Khazgorm"}}},
    [844] = {n="La menace des trotteurs des plaines", d="Collecter 7 Becs de trotteurs des plaines et les apporter à Sergra Darkthorn à la Croisée.", tgo={{"Grand trotteur des plaines", "Trotteur des plaines hargneux", "Trotteur des plaines fugitif"}}},
    [845] = {n="Les zhévras", d="Tuer des Messagers zhévras et apporter 4 Sabots de zhévra à Sergra Darkthorn à la Croisée.", tgo={{"Messager zhévra", "Etalon zhévra", "Coursier zhévra"}}},
    [847] = {n="La ruse du raptor", d="Parler à Tor'gan."},
    [848] = {n="Spores fongiques", d="Apporter 4 Spores fongiques à l'Apothicaire Helbrim à la Croisée.", objs={"Champignon chargé"}},
    [850] = {n="Les chefs des Kolkar", d="Apporter la Tête de Barak à Regthar Deathgate, à l'ouest de la Croisée.", tgo={{"Barak Kodobane"}}},
    [851] = {n="Verog le Derviche", d="Apporter la Tête de Verog à Regthar Deathgate, à l'ouest de la Croisée.", tgo={{"Verog le Derviche"}}},
    [852] = {n="Hezrul Marque-de-sang", d="Apporter la Tête d'Hezrul à Regthar Deathgate, à l'ouest de la Croisée.", tgo={{"Hezrul Marque-de-sang"}}},
    [853] = {n="Apothicaire Zamah", d="Apporter les Spores fondues à l'Apothicaire Zamah à Thunder Bluff, avant que la limite de temps ne soit dépassée."},
    [854] = {n="Un voyage à la Croisée", d="Parler à Thork, à la Croisée des Tarides."},
    [855] = {n="Les bracelets de centaures", d="Apporter 15 Bracelets de centaures à Regthar Deathgate, à l'ouest de la Croisée.", tgo={{"Querelleur kolkar", "Légion-tempête kolkar", "Coursier kolkar"}}},
    [858] = {n="Contact", d="Récupérer la Clé de contact et l'apporter à Wizzlecrank.", tgo={{"Superviseur Lugwizzle"}}},
    [860] = {n="Sergra Darkthorn", d="Parler à Sergra Darkthorn, à la Croisée."},
    [861] = {n="La voie du chasseur", d="Apporter 4 Griffes de Rôdeurs des basses plaines à Melor Stonehoof à Thunder Bluff.", tgo={{"Rôdeur des basses plaines"}}},
    [863] = {n="La fuite", d="Protéger Wizzlecrank et le Déchiqueteur gobelin volé jusqu'à Sputtervalve à Ratchet."},
    [865] = {n="Les cornes de raptors", d="Collecter 5 Cornes de raptors intactes prises sur des Faucheurs solécaille, et les apporter à Mebok Mizzyrix à Ratchet.", tgo={{"Faucheur solécaille", "Ishamuhale", "Takk le Bondisseur"}}},
    [867] = {n="Les harpies pillardes", d="Collecter 8 Griffes d'Ensorçaile.\nLes apporter à Darsok Swiftdagger à la Croisée.", tgo={{"Harpie Ensorçaile", "Volplume Ensorçaile", "Tueuse Ensorçaile"}}},
    [868] = {n="La chasse aux œufs", d="Apporter 12 Œufs de silithide et la Griffe d'excavation à Korran, à la Croisée.", objs={"Antre des silithides"}},
    [869] = {n="Les raptors voleurs", d="Apporter 12 Têtes de raptor à Gazrog, à la Croisée.", tgo={{"Flagellant solécaille", "Hurleur solécaille", "Faucheur solécaille"}}},
    [870] = {n="Les Bassins oubliés", d="Rendre compte de vos découvertes à Tonga Runetotem."},
    [871] = {n="Stopper les attaques des hurans", d="Dans la tribu Tranchecrin, tuer 8 Sourciers, 8 Tisseuses d'épines et 3 Chasseurs, puis retourner voir Thork.", tgo={{"Sourcier Tranchecrin"}, {"Tisseuse d'épines Tranchecrin"}, {"Chasseur Tranchecrin"}}},
    [872] = {n="La perturbation cesse", d="Tuer 8 Géomanciennes Tranchecrin, 8 Défenseurs Tranchecrin et Kreenig Grondegroin.\nPuis apporter la Défense de Kreenig Grondegroin à Thork à la Croisée.", tgo={{"Géomancienne Tranchecrin"}, {"Défenseur Tranchecrin"}, {"Kreenig Grondegroin"}}},
    [875] = {n="Lieutenants harpies", d="Rassembler 6 Anneaux de lieutenant harpie sur des Tueuses Ensorçaile et les apporter à Darsok Swiftdagger à la Croisée.", tgo={{"Tueuse Ensorçaile"}}},
    [876] = {n="Serena Plumesang", d="Tuer Serena Plumesang et apporter sa tête à Darsok Swiftdagger à la Croisée.", tgo={{"Serena Plumesang"}}},
    [877] = {n="L'oasis stagnante", d="Retourner voir Tonga Runetotem à la Croisée, après avoir enquêté à l'Oasis stagnante.", objs={"Fissure bouillonnante"}},
    [878] = {n="Tribus en guerre", d="Tuer 6 Sourciers Dos-hirsute, 12 Tisseurs d'épines Dos-hirsute et 12 Géomanciennes Dos-hirsute puis retourner auprès de Mangletooth au camp Taurajo dans les Tarides.", tgo={{"Sourcier Dos-hirsute"}, {"Tisseur d'épines Dos-hirsute"}, {"Géomancienne Dos-hirsute"}}},
    [879] = {n="Une trahison de l'intérieur", d="Tuer Nak, Kuz et Lok Plaie-des-orcs et apporter leurs crânes à Mangletooth au Camp Taurajo dans les Tarides.", tgo={{"Kuz"}, {"Nak"}, {"Lok Plaie-des-orcs"}}},
    [880] = {n="Source de vie", d="Apporter 8 Carapaces de Gueules d'acier altérées à Tonga Runetotem à la Croisée.", tgo={{"Gueule d'acier des oasis", "Oasis Snapjaw Hatchling"}}},
    [881] = {n="Echeyakee", d="Apporter la Peau d'Echeyakee à Sergra Darkthorn à la Croisée.", tgo={{"Echeyakee"}}},
    [882] = {n="Ishamuhale", d="Apporter le Croc d'Ishamuhale à Jorn au Camp Taurajo.", tgo={{"Ishamuhale"}}},
    [883] = {n="Lakota'mani", d="Apporter le Sabot de Lakota'mani à Jorn au Camp Taurajo."},
    [884] = {n="Owatanka", d="Apporter l'Epine caudale d'Owatanka à Jorn au Camp Taurajo."},
    [885] = {n="Washte Pawne", d="Apporter la Plume de Washte Pawne à Jorn Skyseer au Camp Taurajo."},
    [886] = {n="Les oasis des Tarides", d="Parler à Tonga Runetotem à la Croisée."},
    [887] = {n="Les flibustiers des Mers du sud", d="Tuer 12 Brigands et 6 Canonniers des Mers du Sud pour Gazlowe de Ratchet.", tgo={{"Brigand des Mers du sud"}, {"Canonnier des Mers du sud"}}},
    [888] = {n="Course à la lentille", d="Retrouver la Cargaison de bottes et la Lentille de télescope pour Gazlowe de Ratchet.", objs={"Marché de Drizzlik", "Fragile - Ne pas jeter"}},
    [890] = {n="La livraison perdue", d="Apporter le Grand Livre de Gazlowe au Maître des quais Dizzywig."},
    [891] = {n="Sous le feu de l'ennemi", d="Le capitaine Thalo'thas Brightsun de Ratchet veut que vous collectiez 10 Médailles de Theramore et que vous tuiez le Capitaine Fairmount, le Canonnier Whessan et le Canonnier Smythe.", tgo={{"Capitaine Fairmount"}, {"Canonnier Whessan"}, {"Canonnier Smythe"}, {"Soldat de marine de Theramore", "Protectrice de Theramore", "Capitaine Fairmount"}}},
    [892] = {n="La livraison perdue", d="Rapporter le Grand Livre de Gazlowe à Gazlowe à Ratchet."},
    [893] = {n="Des armes de choix", d="Apporter un Poignard de Tranchecrin, une Baguette Tranchecrin carbonisée et un Bouclier Tranchecrin à Tatternack Steelforge au camp Taurajo dans les Tarides.", tgo={{"Guide Tranchecrin", "Traqueur Tranchecrin"}, {"Prophète Tranchecrin"}, {"Frénétique Tranchecrin"}}},
    [894] = {n="Samophlange", d="Accéder à la Console de contrôle au Centre de recherches de la KapitalRisk."},
    [895] = {n="ON RECHERCHE : baron de Longrivage", d="Apporter la tête du baron de Longrivage à Gazlowe à Ratchet.", tgo={{"Baron de Longrivage"}}},
    [896] = {n="La bonne fortune d'un mineur pauvre", d="Prendre l'Emeraude œil-de-chat à l'un des Surveillants ou l'un des Massacreurs de la KapitalRisk pour le Maître des quais Dizzywig à Ratchet.", tgo={{"Massacreur de la KapitalRisk", "Surveillant de la KapitalRisk", "Chef Copperplug"}}},
    [897] = {n="Le Moissonneur", d="Apporter la Tête du Moissonneur à Jorn Skyseer."},
    [898] = {n="Hors du fort", d="Escorter en toute sécurité Gilthares Firebough jusqu'au capitaine Brightsun à Ratchet."},
    [899] = {n="Consumé par la haine", d="Apporter 60 Défenses de huran Dos-hirsute à Mankrik, à la Croisée.", tgo={{"Chasseur Dos-hirsute", "Sourcier Dos-hirsute", "Tisseur d'épines Dos-hirsute"}}},
    [900] = {n="Samophlange", d="Fermer la Valve de contrôle du carburant, la Valve de réglage et la Valve de contrôle principale, puis utiliser à nouveau la console de contrôle.", objs={"Valve de commande principale", "Valve de contrôle du carburant", "Valve de réglage"}},
    [901] = {n="Samophlange", d="Obtenir la Clé de la console de l'artisan Sniggles, puis l'utiliser sur la console de contrôle.", tgo={{"Artisan Sniggles"}}},
    [902] = {n="Samophlange", d="Rapporter le Samophlange à Sputtervalve à Ratchet."},
    [903] = {n="Les rôdeurs des Tarides", d="Collecter 7 Griffes de Rôdeur des savanes pour Sergra Darkthorn à la Croisée.", tgo={{"Rôdeur des savanes"}}},
    [905] = {n="Les Faucheurs furieux", d="Tuer des raptors solécaille et récupérer leurs plumes. Placer ces plumes dans les 3 nids de Faucheurs solécaille, puis retourner voir Sergra Darkthorn à la Croisée.", objs={"Nid de raptor bleu", "Nid de raptor jaune", "Nid de raptor rouge"}},
    [906] = {n="Une trahison de l'intérieur", d="Apporter le Crâne de Lok à Thork à la Croisée des Tarides."},
    [907] = {n="Les lézards-tonnerre enragés", d="Apporter 3 doses de Sang de lézard-tonnerre à Jorn Skyseer, à Camp Taurajo.", tgo={{"Orageux", "Tête-tonnerre", "Groin-tempête"}}},
    [913] = {n="Le cri du faucon-tonnerre", d="Trouver et tuer un faucon-tonnerre, et rapporter ses ailes à Jorn Skyseer, au Camp Taurajo.", tgo={{"Jeune faucon-tonnerre", "Grand faucon-tonnerre", "Faucon-tonnerre des nuages"}}},
    [914] = {n="Les druides du Croc", d="Apporter les Gemmes de Cobrahn, d'Anacondra, de Pythas et de Serpentis à Nara Wildmane à Thunder Bluff.", tgo={{"Seigneur Cobrahn", "Forme de serpent Cobrahn"}, {"Dame Anacondra"}, {"Seigneur Pythas"}, {"Seigneur Serpentis"}}, star={"Bâton au croissant", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}},
    [959] = {n="Fuite de porto aux docks", d="Le grutier Bigglefuzz de Ratchet veut que vous repreniez la Bouteille de porto vieille de 99 ans à Magglish le Dingue, qui se cache dans les Cavernes des lamentations.", tgo={{"Magglish le Dingue"}}},
    [962] = {n="Fleur de serpent", d="L'Apothicaire Zamah à Thunder Bluff veut que vous récoltiez 10 Fleurs de serpent.", objs={"Fleur de serpent"}},
