    [1093] = {n="Super-Découpeur 6000", d="Trouver le Plan du Super-Découpeur 6000 pour Ziz Fizziks dans les Serres-Rocheuses.", tgo={{"Opérateur de la KapitalRisk"}}},
    [1094] = {n="D'autres instructions", d="Remettre l'Enveloppe scellée à Sputtervalve dans les Tarides."},
    [1095] = {n="D'autres instructions", d="Apporter les nouveaux ordres à Ziz Fizziks dans les Serres-Rocheuses."},
    [1096] = {n="Gerenzo Wrenchwhistle", d="Apporter le Bras mécanique de Gerenzo Wrenchwhistle à Ziz Fizziks dans les Serres-Rocheuses.", tgo={{"Gerenzo Wrenchwhistle"}}},
    [1098] = {n="Des Traqueurs noirs à Ombrecroc", d="Trouver les Traqueurs noirs Adamant et Vincent."},
    [1102] = {n="Un destin funeste", d="Apporter le Cœur de Trancheflanc à Stonespire le Vieil, à Thunder Bluff.", tgo={{"Charlga Trancheflanc"}}},
    [1104] = {n="Le venin acide des salines", d="Apportez 6 doses de Venin de scorpide acide à Fizzle Brassbolts, dans les Salines.", tgo={{"Scorpide terrifiant", "Scorpide ravageur", "Dardeur"}}},
    [1105] = {n="Les carapaces durcies", d="Apporter 9 Carapaces de tortue durcies à Wizzle Brassbolts dans les Salines.", tgo={{"Tortue nacrétoile", "Mordeuse nacrétoile", "Tortue fouisseuse nacrétoile"}}},
    [1106] = {n="Martek l'Exilé", d="Apporter la Lettre de Fizzle à Martek l'Exilé dans les Terres ingrates."},
    [1108] = {n="Indurium", d="Apporter 10 Flocons d'indurium à Martek l'Exilé dans les Terres ingrates.", tgo={{"Cogneur Cavepierre", "Chaman Cavepierre", "Briseur d'os Cavepierre"}}},
    [1109] = {n="Corvée de guano", d="Apporter 1 tas de Guano du kraal au Maître Apothicaire Faranell à Fossoyeuse.", tgo={{"Chauve-souris du kraal", "Grande chauve-souris du kraal", "Chasseur aveugle"}}},
    [1110] = {n="Pièces de chariot explosif", d="Apporter 30 Pièces de Chariot explosif à Kravel Koalbeard des Salines.", objs={"Décombres de chariot explosif"}},
    [1111] = {n="Maître des quais Dizzywig", d="Apporter la Commande de Kravel au Maître des quais Dizzywig à Ratchet."},
    [1113] = {n="Des cœurs zélés", d="Le maître apothicaire Faranell, à Fossoyeuse, veut 20 Cœurs zélés.", tgo={{"Maître-chien Loksey", "Herod", "Commandant écarlate Mograine"}}},
    [1116] = {n="De la Poussière de rêve dans les marécages", d="Apporter 10 Grains de Poussière de rêve à Krazek à Baie-du-Butin. La Poussière de rêve se récupère sur les dragonnets du marais des Chagrins.", tgo={{"Jeune dragonnet", "Dragonnet rêveur", "Wyrmide vert"}}},
    [1123] = {n="Rabine Saturna", d="Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune. Reflet-de-Lune se trouve entre Gangrebois et le Berceau-de-l'Hiver. Le chemin qui y mène traverse le Repaire des Grumegueules."},
    [1124] = {n="La dévastation", d="Parler à Layo Starstrike, à proximité du Repos des vaillants de Silithus, et lui montrer la Lettre de Rabine."},
    [1125] = {n="Les esprits de Sudevent", d="Libérer l'esprit de 8 Druides torturés et de 8 Sentinelles torturées, dans le village de Sudevent, puis revenir voir Layo Starstrike, au cimetière du Repos des Vaillants de Silithus.", tgo={{"Druide torturé"}, {"Sentinelle torturée"}}},
    [1126] = {n="Une ruche dans la tour", d="Escalader la Tour du village de Sudevent, et trouver un moyen de mettre la ruche des silithides en activité. Toute chose inhabituelle doit être rapportée à Layo Starstrike, au cimetière du Repos des vaillants de Silithus.", tgo={{"Embusquée de la Ruche'Ashi"}}},
    [1144] = {n="Willix l'Importateur", d="Escorter Willix l'Importateur hors du Kraal de Tranchebauge."},
    [1147] = {n="L'essaim s'agrandit", d="Tuer 5 Chercheurs silithides, 5 Bourdons silithides et 5 Envahisseurs silithides, puis retourner voir Moktar Krin aux Mille pointes.", tgo={{"Chercheur silithide"}, {"Bourdon silithide"}, {"Envahisseur silithide"}}},
    [1148] = {n="Des parties de l'essaim", d="Apporter 1 Coeur de silithide, 5 Serres de silithide et 3 Carapaces de silithide intactes à Korran, à la Croisée.", tgo={{"Chercheur silithide", "Envahisseur silithide", "Ravageur silithide"}, {"Chercheur silithide", "Envahisseur silithide", "Ravageur silithide"}, {"Chercheur silithide", "Envahisseur silithide", "Ravageur silithide"}}},
    [1149] = {n="L'épreuve de la Foi", d="Si vous avez la Foi, sautez des planches qui dominent les Mille pointes."},
    [1150] = {n="L'épreuve de l'Endurance", d="Apporter la Griffe de Grenka au traqueur des plaines Dorn, aux Mille pointes.", tgo={{"Grenka Hurlesang"}}},
    [1151] = {n="L'épreuve de la Force", d="Apporter des Fragments de Rok'Alim au traqueur des plaines Dorn dans les Mille pointes.", tgo={{"Rok'Alim le Marteleur"}}},
    [1152] = {n="L'épreuve de la Connaissance", d="Trouver Braug Dimspirit près de l'entrée de la Perce des Serres dans les Serres-Rocheuses."},
    [1154] = {n="L'épreuve de la Connaissance", d="Trouver l'Héritage des Aspects et l'apporter à Braug Dimspirit, à côté de l'entrée de la Perce des Serres, dans les Serres-Rocheuses.", objs={"L'Héritage des aspects"}},
    [1159] = {n="L'épreuve de la Connaissance", d="Trouver Parqual Fintallas à Fossoyeuse."},
    [1160] = {n="L'épreuve de la Connaissance", d="Trouver « Les commencements de la menace des morts-vivants » et le rapporter à Parqual Fintallas à Fossoyeuse.", objs={"Naissance de la menace des morts-vivants"}},
