    [95034] = {n="La dette", d="Parlez avec Lumina Chantelevent, au Sépulcre.", tgo={{"Lumina Chantelevent"}}},
    [95036] = {n="Une lame caressée par la lune", d="Allez voir Trevan Rol, au Sépulcre, et apportez-lui les matériaux nécessaires.", tgo={{"Trevan Rol"}, {}, {"Sculpteur gobelin"}, {}, {}}},
