    [95121] = {n="Saveurs maritimes", d="Récupérez 12 yeux de Murloc et 6 morceaux de chair de clampant des sables pour Fimbo Lubrimitz.", tgo={{"Oracle murloc", "Frôle-marée murloc", "Guerrier murloc"}, {"Clampant des sables", "Clampant du rivage"}}},
