    [96781] = {n="Qu'est-ce qu'ils manigancent ?", d="Volez le rapport d'éclaireur de Barton, puis rapportez-le à Myrokos Sourdeforme, au manoir de Ravenholdt.", tgo={{"Barton"}}},
