    [96876] = {n="Le sac perdu d'Ukor", d="Rapportez son sac à Ukor dans le sud de Durotar."},
    [96877] = {n="Le sabot d'Halikor", d="Rapportez le sabot d'Halikor à Orgrimmar."},
